/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20161129-8","meetingId":"h28-cm11","date":"2016年11月29日","dateIso":"2016-11-29","committee":"建設委員会","time":"午前１０時００分～午後 ２時５４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件整理しています。","topics":[{"id":"topic-01","title":"北品川五丁目第１地区市街地再開発組合施行による都市基盤整備工事","agenda":"北品川五丁目第１地区市街地再開発組合施行による都市基盤整備工事","exchanges":[{"speaker":"西本委員","kind":"質問","question":"今後どういうアプローチをされるのでしょうかというのが１点目と、２点目の、要は足の悪い方はどういう移動の仕方になるのでしょうか。今まで、そこはエレベーターを使って行っていたと思うのですけれど、足の悪い方の動線がどうなっているのかをお聞きしたいと思います。","respondent":"稲田都市開発課長","answer":"非常に困難なところですけれども、何とかこれをつなげることが、歩行者のネットワークを確立するところですので、ぜひともこれは進めていきたいです。足の悪い方はこの階段も非常に、ここに見える階段の段差を解消しながら…","id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"移設したところを見ると、ニューシティに行くとき遠くなってしまっているのかなという、それはないのでしょうか。わかりやすさというのはどうなっているのか、説明を求めました。","respondent":"稲田都市開発課長","answer":"若干は、ずれましたけれども、動線的にはスムーズに行けるものです。1)の写真を見ていただきますと、私ども現場を確認した上では、目立たないというところはなかったと思います。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この施行は市街地再開発組合でやっていると思いますが、費用的にはどのぐらいかかっているのでしょうか。１、２それぞれ、別々に教えてもらえれば。","respondent":"稲田都市開発課長","answer":"大雑把で目黒川デッキが１０億円、デッキ階段が４億円、Ｏ歩道橋の混雑緩和が７億円と聞いております。これはもう本当に大雑把な数字で、概略という具合でお聞き取りいただければと思います。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これだけでも合計２１億円という大きな金額がこの開発に支出されてきて、当初の計画と随分、その辺の影響というのはどういうふうに考えているのか。今後の計画において、資金的に開発組合は大丈夫なのかというのが気になるので、その辺のご見解を説明を求めました。","respondent":"稲田都市開発課長","answer":"今回、デッキ暫定階段はプラスアルファでかかった４億円ですが。これをつなぐまでの予算も当初から組んでおりましたので、今回のことで組合等の管理に影響してくるというものはないというところを聞いております。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ちょっともう一回確認させてください。これは結局つなげられないから、代わりにやった部分というのはないのか尋ねました。","respondent":"稲田都市開発課長","answer":"大変申し訳ございません、説明がちょっとうまくなくて。これが約４億円です。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"意見","question":"開発全体からしたら４億円というのは大したことない金額かもしれないけれど、これが、次につないでいく中で影響してこなければいいのだけども。区としてもやっていってくださいという、これはもうお願いするしかないと思うのですが、との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"塚本委員","kind":"確認","question":"今の目黒川デッキ暫定階段のほうで確認ですけれど、一応、これは本格的な接続ができた場合にどういう扱いになるのでしょうか。取り壊してしまうということでしょうか、そういうことはないのか尋ねました。","respondent":"稲田都市開発課長","answer":"この階段の将来つながったところにおきましては、どうするかという取扱いについてはまだ決めておりません。道路管理者と協議しながら、どうするかというところだと思います。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"決めていないということは取り外しもあり得るということかと思うのですが、つけておくと、つけておいたで、取り外したほうがいい理由というのが何かあるのであれば教えていただけますか尋ねました。","respondent":"稲田都市開発課長","answer":"ところが、これは非常用の階段にもなるではないかというような話になれば、せっかくお金をかけてつくったので残しておこうかという考えもあります。そういうところで、今後、将来に向けてはまだ決めてはいないです。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、道路管理者と相談すると言うと、道路管理者は、区ではなくなるのですか。天王洲の通路などもたしか、大きな金額ででき上がったのを区が管理していると思うのですけれど、今後、非常用の暫定階段はどこが管理するのか。","respondent":"稲田都市開発課長","answer":"区のほうに引き継がれまして、区が基本的には管理する。ただ、維持管理上は管理組合が管理していくというものです。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問","question":"７億円で、２１億円かかっているということで、全て再開発組合が費用負担ということでいいのでしょうか。こういった混雑解消とか暫定階段というのは、開発の中では今までなかったことなのだと思われているのか、その辺を伺いたいと思います。","respondent":"稲田都市開発課長","answer":"そこに入ってくる人口や、通る人たちの量等も考えて、道を広くしなければいけない。今回の場合は歩道橋の入口を広げたほうが、非常に人がスムーズに行けるというようなことで、計画的にやっているものです。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"どこからどれぐらい、この工事に関しては入ったのか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"先ほどは全体的な話をしましたが、このＯ歩道橋の拡幅とかデッキの工事におきましては補助金は入っていないところです。","id":"exchange-011"}]},{"id":"topic-02","title":"品川区の環境に関する三計画の実績報告等","agenda":"品川区の環境に関する三計画の実績報告等","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"重点プロジェクト１で民間活力を活用した再生可能エネルギーの導入促進とありまして、都市部でも効果が高いと思われる再生可能エネルギーがあると思うのですけれども、太陽光発電以外の再生可能エネルギーの今後の活用などは検討されているのか尋ねました。","respondent":"三ツ橋環境課長","answer":"品川区として、なかなか地域の部分などが、選定する地域に関してなかなか難しい部分があります。しかしながら、来年策定する予定です環境計画においては、太陽光以外のものについても引き続き検討しながら取り組んでいきたいと思います。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ太陽光発電以外の再生可能エネルギーの導入も積極的に進めていっていただきたいと考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"これから改訂が今度あるのですよね、その改訂に向けて、このポイントは変えていかないといけないというようなところがあるのかどうか。でも品川区の現状とは合わないから、今後変えていくための、こういう方向でというのが何かあれば教えてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"そのあたりを一番注視しながら、ＣＯ２の排出量にする目標がいいのか、そのあたりを検討しながら進めていこうと思うところが改訂のポイントです。太陽光というのが、ほかに例えばどこかのモデル地区を設けて何かをするということも考えながら…","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"それぞれ関係しながらということなのでしょうけれども、どうなのでしょう、区民の人たちの意識というのと事業者に対する意識。やはり意識づけ、動機づけというものを具体的なところに落とし込んでいってほしいと思いますが、それについての考えをお願いします。","respondent":"三ツ橋環境課長","answer":"もう、東日本大震災があってから５年経過しておりまして、平成２３年当初よりも意識が少し薄れているのが現状にあると考えています。みんなどれだけ対応できるのか、区としても対応してまいりたいと思いますし、区民に対して啓発してまいりたいと考えています。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２ページのところの重点プロジェクト３の電気自動車の有効活用プロジェクトということで、私もエコフェスタにお邪魔して実際に見ました。それともう一つですが、これも具体的に５カ所と書いてある場所、５カ所ということで今進めている場所を説明を求めました。","respondent":"三ツ橋環境課長、和田河川下水道課長","answer":"区としてできること、また民間事業者に任せることというものもありますので、このあたりを具体的に検討してまいりたいと考えています。実際には、民間事業者が取り組んでいる方向であれば… 水辺に親しめる空間を５カ所以上、我々、河川下水道課では平成２４年度から整備を進めております。それから平成２５年度には、平成２７年度、品川区の東品川清掃作業所脇の水辺広場の整備を行ってまいりました。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問","question":"その民間の会社というのは、大手企業の例えばトヨタとか日産とか、そういったところと一緒にやっていくという考え方でよろしいのでしょうか。４年後のオリンピック・パラリンピックを見据えるということで、具体的にこの辺だなどという検討をしているところがあれば説明を求めました。","respondent":"三ツ橋環境課長、和田河川下水道課長","answer":"カーシェアリングにつきましては、駐車場、パーキングの業者がカーシェアリングを進めておりまして、そちらです。駐車場、パーキング会社の中でカーシェアリングをされておりますので、そちらを示していたものです。 もう一カ所の候補地ですけれども、まだ計画段階ですが、現段階では、天王洲の東品川二丁目６番の天王洲運河沿いです。寺田倉庫の、西側の天王洲運河沿いがまだ開放されてございませんので…","id":"exchange-017"},{"speaker":"塚本委員","kind":"確認","question":"速報値で基準年比８.６％減を達成できたというところなのですが、これは区役所１m2あたりということは、この本庁舎ということでいいのでしょうか。電気のエネルギー量からというのは、それ以外にはどういう形で、品川区役所の排出量というのには何が含まれてくるのかというところを説明を求めまし…","respondent":"三ツ橋環境課長","answer":"実行計画の対象の場所ですけれども、区役所だけではなく区役所の出先も含めて、区全体のことを指しております。次に総排出量ですが、電気がほとんどで、今こちらに書いておりますように電気が主なものですけれども、そのほかガスなどが含まれております。","id":"exchange-018"},{"speaker":"塚本委員","kind":"質問","question":"全体的な温暖化、なかなか困難な状況下の中での８.６％減であろうと、なかなかすごいことだったと思いますけれども。その基準年というのを何年にしているのかということを１つお伺いしたいのと、その上で、今回８.６％達成に至った大きな要因について説明を求めました。","respondent":"三ツ橋環境課長","answer":"その中で、やはり紙の削減の取組みですとか、また節電の取組みなどにつきまして実施しております。そこで皆さんが、ちょっとした取組みであってもきちんと水平展開していくことなどを実施しております。","id":"exchange-019"},{"speaker":"塚本委員","kind":"意見","question":"なかなかＣＯ２を減らすのは難しいエネルギー環境にある中で、このような形で進めていっていただいて非常にすばらしいと思いますので、今後ともぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"グラフで見ると１,３２４、これをさらに２５％削減していくわけですから、さらに区全体での取組みが必要なのだろうと私は思うのですけれども。いろいろとイベントはやられて、さらに進めていくために、区としてはどういった姿勢で区民に訴えていくのかというのを伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"区が率先してＣＯ２の削減、高い目標を掲げ、また実効効果のある目標を掲げながら取り組まないといけないと考えています。そのような中で、来年度の環境計画に向けては、さらに推進してまいりたいと考えています。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり開発工事中、またその後にもさらに出されるＣＯ２というのが、一人一人の頑張りを無駄にするほど出しているのではないかと思うのです。なので、まちづくりのあり方というのも、環境の面からも考えていかなくてはいけないのではないかと思うのですけれども、その辺はいかがか尋ねました。","respondent":"三ツ橋環境課長、鈴木建築課長、稲田都市開発課長、藤田都市環境部長","answer":"ビルメンテナンスシステム、ＢＥＭＳなどを使っておりますと、非常に省エネ効果が高いということがいろいろな報告でされております。… 空調あるいは断熱、ガラスサッシを含めて、低炭素に向けた建物の開発が今後も行われていくという流れになってあります。 東京都のほうに建築物環境計画書というものを必ず提出しておりまして、環境、ＣＯ２の削減等に寄与しています。 この間、先ほど来お話をさせていただいた各所管で進める形の中で、エネルギーの使用量については減少しているという形になってあります。…","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"国が出している基準年でいいのでしょうかということと、今、世界は１９９０年比で削減していこうということで各国が目標を出しているわけです。そうであれば、私は、もうちょっと区としては、国をさらに上回る積極的な目標が必要なのではないかと思うのですけれども、いかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"したがいまして、平準化できるのが平成２１年度でしたので、そのときに基準年を定めております。それに対して目標を高く掲げるというように考えておりますので、実際、品川区として取り組むべきことを取り組んでいきたいと思います。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、ごめんなさい、先ほど部長が言ったａのところの基準年というのは、平成２１年度ということなのですかね。やはり日本がしっかりと、私たちもいろいろ勉強しながら、一緒にさらに削減していくように頑張っていきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問・要望","question":"放置自転車は、ぜひとも今後とも積極的に、放置自転車の撤去を進めていただきたいと考えております。目標が平成３０年までに４地区ということで、あと２カ年ほどしかないのですけれども、現在わかっているところで教えていただけないか尋ねました。","respondent":"三ツ橋環境課長、藤田都市環境部長","answer":"景観地区というのは、ちょっと所管と調整していきながら、実際にこちらにつきましては、所管と調整しています。 継続して調整しているのは、武蔵小山の周辺について、重点地区として調整を進めているところです。残りの１地区については、水辺であるとか、幾つかちょっと候補がありまして、現段階ではどうするかというところを検討しています。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"では、今おっしゃられた大崎、武蔵小山というのが、平成２５年度から平成２７年度のいずれかに入ってくるということか尋ねました。","respondent":"中村都市計画課長","answer":"今、策定が、大崎についてはこの６月に策定されたばかりですので。したがいまして、旧東海道が、今、実際に動いているところということになりますので、その部分の実績ということになろうかと思います。","id":"exchange-026"}]},{"id":"topic-03","title":"しながわ中央公園（拡張部）の開園式","agenda":"しながわ中央公園（拡張部）の開園式","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"ヘリコプターを用いた自衛隊と区の連携訓練とありまして、また完成イメージ図でもヘリコプターが飛んでいる図があるのですけれども、実際にヘリコプターが飛んできて着陸するというような訓練が行われるのか尋ねました。","respondent":"溝口公園課長","answer":"今現在、自衛隊と最終調整をしていますが、今現在のところでは、この完成イメージ図に描いてあるようなヘリコプターに現地に来ていただいて着陸して、そういったところでの訓練・イベントを開催できるよう予定しています。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"この開園式は、もちろん区民の方どなたでもいいのでしょうか。告知はどうされるのか尋ねました。","respondent":"溝口公園課長","answer":"今回、イベントにつきましては、区民の方、誰でも参加できるように考えております。地元の町会等にご説明に上がるとともに、１月１１日号の広報で、またイベントを開催することについての告知を行っていきたいと考えているものです。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問","question":"完成後の公園を見ていると、中小企業センターを外しているではないですか。やはりこういう図面を出してきたときに、これだけ大きな広場になるのかというのがちょっと気になったのですけれども。","respondent":"溝口公園課長","answer":"今回、私どもといたしましては、公園の視点ということで、今現在、開園している部分も含めてイメージをつけたということで、こういう形にしています。今後につきましては、区民の方に誤解を与えないように…","id":"exchange-029"},{"speaker":"塚本委員","kind":"質問・要望","question":"周知についてお伺いしたいのと、どうなのだろう、区民の方は普通に皆さん見学に来られるのですかね。いずれにしても、無事故でできるようにということで、重ね重ねお願いしたいと思いますけれど、周知についてだけご答弁ほしいと求めました。","respondent":"溝口公園課長","answer":"近隣の方への周知につきましては、当日、やはり音、または風等、予想されますので、しっかりと、この後、報告の後に一軒一軒回って、その説明に回りたいと考えております。","id":"exchange-030"}]},{"id":"topic-04","title":"舟運社会実験に伴う目黒川の橋梁ライトアップの実施","agenda":"舟運社会実験に伴う目黒川の橋梁ライトアップの実施","exchanges":[{"speaker":"西本委員","kind":"質問","question":"ＬＥＤを使うので、あまり経費はかからないとは思うのですけれど、どのぐらいの予算を考えているのでしょうか、説明を求めました。","respondent":"和田河川下水道課長","answer":"こちらは設置費、それから照明が一部レンタルしていますからレンタル費、それから維持費等を含めまして、合計で７００万円ほどを予算として計上しています。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"これは、昭和橋とか、いろいろライトを選ばれたのでしょうが、こういうのにするというのは、何か要望があってですか。ご意見などいろいろ聞かれてこういうのにしたのか、その辺はいかがか尋ねました。","respondent":"和田河川下水道課長","answer":"委託会社の中で、それから周りの雰囲気とどのように調和するかというようなことを考えて、この４基をこのように照らすということを考えたものです。費用対効果を考えて、予算を考えながら、このようなデザインとさせていただいたところです。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"７００万円ですから、７００万円の中にその経費が入っているのかと思うのですけれど、いろいろ工夫できるとは思うんです。それも大きな目玉になってくると思うので、予算化も含めていろいろ考えていただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれど、ライトアップの時間帯に舟は通しているのか尋ねました。","respondent":"和田河川下水道課長","answer":"２つの舟運事業者が、これを１つの目玉として、るるコースをつくって遡上していると聞いています。今のところ舟運事業者にヒアリングは行っていませんので、今後行って、どのような効果があったかというのを検証したいと思います。","id":"exchange-034"}]},{"id":"topic-05","title":"本日は、震災対策に関することのうち、災害時の受援","agenda":"本日は、震災対策に関することのうち、災害時の受援","exchanges":[{"speaker":"西本委員","kind":"質問","question":"質問があるのですが、まず１つは、その違いはどこから来るのでしょうかということです。区の考え方として、区の整理の仕方、これからの進め方について説明を求めました。","respondent":"古巻防災課長","answer":"災害対策本部でという形になりますけれども、災害対策本部１本でやるのがいいのかどうか、その辺も含めて今後検討していきたいと考えております。訓練等も今後、社会福祉協議会と検討していますので…","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"ただ単に協定を組んだだけであって、具体的な行動提起までしているのでしょうかというのを、ちょっとお聞きしたいと思います。何か具体的にあるのですか、社協との調整の仕方。","respondent":"古巻防災課長","answer":"先ほど、輸送拠点のところでご説明させていただきましたけれども、一定ルールに従ってやるというような流れの整理をしてはいるところです。そちらと防災課の担当者の間で協議して、訓練については…","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひそういう考えのもとでやっていただきたいですし、考えておられると思いますけれども、それをあわせて考えていただきたいと思っています。意見で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"高橋（伸）委員","kind":"質問","question":"三年前ですか、協定を結んだと思うのですけれども、これは協定を改訂すればそれも可能なのかどうかを教えてください。発災後、基本的なルールというのをどういうふうにこれから定めていくのか、基本的なということの具体的な内容を説明を求めました。","respondent":"古巻防災課長","answer":"区内に１４スタンドがありますけれど、必ずその分だけはあるような形で備蓄していただくというような形の協定内容になっています。こちらはかなり具体的な内容を含めて計画をつくっているところです。","id":"exchange-038"},{"speaker":"高橋（伸）委員","kind":"質問","question":"燃料のことなのですけれど、全ての車両について常時一定量の燃料を維持するよう、給油の基本的なルールをということですから、この全ての車両に常時一定量の燃料ということは、満タン状態を全ての車両に対して維持していくようにこれからルールを定めるということの解釈でよろしいのか尋ねました。","respondent":"古巻防災課長","answer":"乗用車に関しましては、燃料が半分になったら必ず満タンに給油するようにということでルール化しておりまして、徹底がされているはずです。全ての車両について燃料が、発災時にも動けるように、きちんと給油しておくというようなルールになっております。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"幾つかお伺いしたいと思います。発災後の時間の経過とともに、時間経過についてのことでの考え方というのを、ひとつお伺いしたいと思います。","respondent":"古巻防災課長","answer":"一定の検討の考え方、枠組みは確かにあるのですけれど、受援に関しましても、当然そういった考え方をよりはっきりとさせていく。ただ今後、タイムラインを意識して、計画の修正等進めていきたいと考えているところです。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"それと、今伺いましたとおりタイムラインというような視点も含めて受援というものを考えていく、それはその時その時できっといろいろな状況があって。品川区として今どういうところに困っていて、適切な要請の発信というのですか、今の防災課としての考えをお伺いしたいです。","respondent":"古巻防災課長","answer":"情報の収集、それから伝達ですけれども、当然、適切・正確な情報の発信ということも重要なポイントではあると考えています。こういった情報の流れというのでしょうか、流通というか、そういった中に含めて検討していく必要はあると考えております。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問","question":"全てで５２ですか、協定を組んでいる、結んでいると。そういうところが大事かと思うのですが、何か今そこについてお考えがあればお伺いしたいと思います。","respondent":"古巻防災課長","answer":"具体的な話というのは、今、現状だとなかなか難しいところはあるのですけれども、具体的にちょっと今お答えする材料がないのですが、そこは発信というところを十分に意識しながら、情報の流れの整理をしていきたいと考えております。","id":"exchange-042"},{"speaker":"塚本委員","kind":"質問","question":"すみません、そういうツールも含めてなのですけれども、いざといったときにどうやって要請をしていこうと。そういう手段、今ある情報伝達ツールといった手段を大いに活用しながら、それに対して何か今のお考えがあればというところでお伺いしたいと思います。","respondent":"松代防災まちづくり部長","answer":"で、私どもは品川区の中での起こったことに対応するということと、広域的な観点で対応するということを。情報がしっかりと集まり、それに対する的確な対応ができるものと思っていますし、訓練もしておるという状況です。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問・要望","question":"これはもう少し詳しくご説明いただきたいのですが、具体的にこういうことをお願いしたいのだみたいなイメージがあるのかどうか。ご説明をもう少し詳しくほしいと求めました。","respondent":"古巻防災課長","answer":"やはり様々な物流が、プロであります物流業者のノウハウといったものを活用していくことが今後必要になってくるのではないかという視点があります。それにプラスしまして、さらに民間のそういったノウハウや人材の活用ができればというふうな考え方で…","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もしそういうイメージがあったら教えていただきたいのと、受援計画を立てる、考えている近隣自治体はあるのかどうかも伺いたいと思います。","respondent":"古巻防災課長","answer":"これはまさに今検討しているところでございまして、何か、わかりやすく章立て等を考えていきたい。例えば大田区ですと、そういった近隣自治体の状況もチェックしながら、品川区の新しい地域防災計画に反映していきたいと考えているところです。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問","question":"平成２９年度の受援計画をつくっていくということだったので、策定委員会みたいなのは、きっとないわけですよね。どういう形で、議会の中でもっと議論できる場をつくるのかとか、そういうイメージはどうか尋ねました。","respondent":"古巻防災課長","answer":"課題でありますとかの整理をしていますけれども、地域防災計画の改定ですので、防災会議等で充分にご審議をいただく。それに先立って当然、そういった過程でいろいろご意見を伺いながらよりよい形でまとめていければと思います。","id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"「受援」などという言葉も意識がなかったので、様々な課題を我々も捉えております。それで、１つ１つというよりも十分ご理解いただいていると思いますので、いい計画を立ててほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"木村副委員長","kind":"質問・要望","question":"(3)輸送体制の中に協力協定に基づく車両というのがあるのですけれども、ここではどのような車両のことを指してのことなのか、ちょっと教えてほしいと求めました。","respondent":"古巻防災課長","answer":"先ほども少しお話しさせていただいたのですけれども、トラック協会との協定がありますので、そちらから車両の提供を受けるということ。それから、流通業者であります赤帽という業者がありますけれど、具体的にはそちらを指しているとご理解いただければと思います。","id":"exchange-048"},{"speaker":"木村副委員長","kind":"質問","question":"今、赤帽と言ったのはバイク便のことを言っているのですか。軽自動車、そうか尋ねました。","respondent":"古巻防災課長","answer":"検討課題の中にも、そういった民間の物流の活用についてというようなことも意識していますので、そういった中で検討を進めていきたいと思います。","id":"exchange-049"},{"speaker":"木村副委員長","kind":"質問","question":"１年後なのかもわからないですけれども、バイク便や自転車便というのが、いざとなったら本当に役に立つのではないかと思います。災害時の臨時離着場というのですか、臨時のところという、またそういう候補地というのは考えているのか尋ねました。","respondent":"古巻防災課長","answer":"西大井広場公園、八潮公園多目的広場、それから大井ふ頭中央海浜公園という５カ所が地域防災計画には記載があります。今、現状の計画の中では５つ想定しています。","id":"exchange-050"},{"speaker":"木村副委員長","kind":"質問・要望","question":"ぜひいろいろなところをまた対象にして、いざというときのために、また場所も増やしていってほしいと求めました。例えばどのような回数、どのような感じで使えるのか、それがわかれば説明を求めました。","respondent":"古巻防災課長、松代防災まちづくり部長","answer":"全体的には東京都に要請して、ローテーションといいましょうか、順繰りに回って対応していただくというような形になろうかと思います。そういうことで、東京都に要請いたしまして調整していただくというような形になろうかと思います。 その状況に応じて活動されると考えていますけれども、１つには、いろいろと医療もしくは物資の輸送等に当たってもらうということを想定しております。そういったものを、今後も十分に協議しながら備えていきたいと思っているところです。","id":"exchange-051"},{"speaker":"木村副委員長","kind":"質問・要望","question":"最悪の状態のことをまずは考えて、いろいろと計画を練っていくことが一番いいのではないかと考えています。これはまた要望でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"若林委員長","kind":"質問・要望","question":"確認といいますか、参考に教えていただきたいのですが、その２カ所ですか。１回と２回、何か今後の自治体との協定等の参考になるのかという思いで確認させてほしいと求めましたけれども、いかがか尋ねました。","respondent":"古巻防災課長","answer":"申し訳ございません。確認いたします。","id":"exchange-053"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区営住宅のような低廉な家賃で子育て世帯が入居できるよう家賃助成を求めます」という質問で。なので、家賃助成をする考えはないということだったのですが、これが八潮でどのように実施されているのかを伺いたいと思います。","respondent":"今井住宅課長","answer":"それぞれの設置主体が空き家の活用や住宅の住替えなども含めて対応しているというふうな状況であるということもあわせて答弁させていただいたところ…は行っている子育て支援について述べていまして、子育て世帯と高齢者世帯との近居の支援に向けて…","id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それ以外にＵＲや住宅供給公社というのは、そうはいっても１０万円を超えてくるというところでは、家賃助成を求めたわけです。そして、この近居割をされている方というのは把握はされていないでしょうか、伺いたいと思います。","respondent":"今井住宅課長","answer":"実際には八潮も、実際にこういう空き室が出て、スムーズにそれぞれの主体ごとで世代交代を進めていただくような形になっているのかと考えています。ですので、現時点での家賃助成は考えていないということでお話ししたところです。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私も八潮の皆さんにお話を伺うと、空いているところは多いと伺うのです。特別、こういったことも対策を進めていかなくてはいけないのではないかと思いますけれども、区のお考えを説明を求めました。","respondent":"今井住宅課長","answer":"一般質問でも申しましたとおり、区としても、第二回定例会でもご答弁申しましたとおり、八潮団地については今後の活性化も含め検討課題と考えておりまして、庁内ＰＴ等を含めて多角的な視点から八潮の課題については検討していく予定です。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"どういう形で、１日例えば何匹加えていくとか、やっていくのでしょうか。餌や道具などというのはどういう形になっているのか尋ねました。","respondent":"溝口公園課長","answer":"１日という形ではありませんけれど、大体、月に５００kgぐらいの魚を放流してやるような形になっております。社会実験的にやる中ですから、どのぐらいの利用が見込まれるのかといったものも含めまして十分検証しながら、今後。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"釣れ過ぎてしまうと２匹しか持って帰れないので、そこそこ加減で釣れる必要があると思うので、ちょっといろいろ考えていただきたい。その兼ね合いをぜひ、もう少し計っていただいて、皆さんが楽しめるように工夫してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"筒井委員","kind":"質問","question":"この予算と、アンケートの結果を踏まえてからだと思うのですけれども、継続するとしたら、利用料金はどのぐらいになるのか尋ねました。","respondent":"溝口公園課長","answer":"実際の利用料金なのですけれど、実際に魚が１匹２００円ぐらい、２匹で４００円という形になりますし、餌代でも１００円くらいかかります。そう考えると、そういった中で適正な金額、または利用する方が利用しやすい金額というのを見定めていきたいと考えているものです。","id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１カ月から２カ月ぐらいの間のお金ということになるのですけれど、担当部署として、この辺はどの程度まで想定しているのか。歳出目的をもう少し説明を求めました。","respondent":"古巻防災課長","answer":"歳出先、場合によっては備蓄品等の購入というのも視野に入れて組むことも可能かというところまでの検討を今しているところですが、そこの間の詳細な。そういったところを入れる、入れないあたりを検討を進めている、詰めているところです。","id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ですから、その辺の仕切りがどうかと、この辺は私どもとして疑問を持っているところがあります。当然、総務委員会で終わっていると思うのですが、こちらの部署として確認だけさせてもらおうと思ったので、その辺の今後の話があれば説明を求めました。","respondent":"古巻防災課長","answer":"今ご指摘いただいた点を含めまして、今後、いただいた意見を踏まえまして検討を詰めていきたいと考えております。予算の中でご提案しますので、よろしくお願いいたします。","id":"exchange-061"},{"speaker":"西本委員","kind":"質問","question":"なので、もっと自由度のあるような使い方が必要になる部分があるのかどうなのか。こういう基金、ただ具体的に何に使うのですかというのがすぐに出ないので、何かちょっとでも具体的なイメージがあれば助かるのですけれども。","respondent":"古巻防災課長","answer":"二日というような短いスパンではなくて、１月ぐらいの単位でやはりどうしても必要になってくるお金という発想で、今考えているところです。特別会計という考えでおりますので、そういった中身で今、予算案を考えているところです。","id":"exchange-062"},{"speaker":"西本委員","kind":"質問・要望","question":"その間こういうので必要だろうなどという下地になるような根拠は、これをつくるにしてもやはり必要になってくるのではないかと思うのです。もっとこういうときにこういうのが必要なのですよというところまで、ぜひ準備していただきたいと思っていますので、今後。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862367?Template=document&Id=4190#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":52928,"voices":164}},{"id":"h28-20161129-9","meetingId":"h28-cm11","date":"2016年11月29日","dateIso":"2016-11-29","committee":"文教委員会","time":"午前１０時００分～午後 ４時３７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を80件整理しています。","topics":[{"id":"topic-01","title":"小規模保育事業等における連携施設の設定","agenda":"小規模保育事業等における連携施設の設定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これがどういうものなのかということなのですが、その園にしか行けないということになるのでしょうか、伺いたいと思います。４園あるところもありますね、これは基準とかそういったものがあるのでしょうか、伺いたいと思います。","respondent":"竹田保育課長","answer":"この連携施設につきましては、ほかの園を希望する方がいらっしゃれば、それは可能です。幅があるというお話ですが、また受け入れ先の認可園にも２歳と３歳の差分でさまざま数字が異なることから、連携施設の多い少ないがあるものです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、できるだけ近隣の園と連携するということですけれども、特に基準とかというものはないということなのでしょうか。西中延のほうは２名分しか差がなかったのですけれども、それで４つの連携園に、お考えを説明を求めました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"先ほど申し上げた基本的な考え方に基づいて設定しておりますので、近隣の園というところが基本です。それから、複数の連携施設になっている園があるということですけれども、こちらの数については精査したものです。 すみません、ちょっと説明が。そういうことはできませんけれども、必ず行き場所は保証されている、こういう仕組みだということでご理解ください。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、基準のほうはここに書かれているのが全てだというところでいいということですかね。この連携施設は今回小規模のほうでの連携施設ということですけれども、認証保育園のほうで何か実施するお考えがあるのか伺いたいと思います。","respondent":"竹田保育課長","answer":"現在、国から連携施設の設定を求められているのは、小規模保育事業等です。認証保育所につきましては、今後数の動向を見ながら検討していきたいと考えております。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"今３歳の壁という言葉も出てきておりますし、小規模と同じ状況だと思いますので、よろしくお願いいたします。そういった、既に申請してしまっている方にも周知をやっていっていただきたいと思うのですが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"毎年１２月１日付で新園の開設情報ならびにさまざまな情報を、お申し込みいただいている方皆さんにご通知差し上げております。今回は、その中に連携の設定についても載せているところです。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"例えば複数の連携施設があって、その受け入れる保育園の３歳児のプラス枠が全て連携園で埋まるというようなこともあり得るということなのでしょうか。どういう形で調整をされるのか尋ねました。","respondent":"竹田保育課長","answer":"その定数枠で連携園については２歳と３歳分の差分を使って、小規模の定数を受け入れるという形です。希望が特定の園に集中した場合は利用調整します。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"何と言ったらいいのですかね、この小規模の方の希望だけで２歳と３歳の定数差分が埋まってしまうような運用もされるのでしょうか。このスケジュールのままだとちょっと難しいと思うのですけれども、どうか尋ねました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"この連携園で全部埋めるのかですが、具体的な運用についてはちょっと今後検討させていただきたいと考えています。状況を見ながら、それぞれ小規模と連携園の数を読みながら判断していきたいと考えています。 ちょっと今の保育課長の説明を聞いて何か誤解があるかもしれないのですけれども、機会の均等は大事なのです。実際に進めてしまうと、どうだというのはちょっとなかなか表示がしづらいもので、これはちょっと別途検討させてください。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは公立の園については粛々とされていくと思うのですけれども、私立の園にも同じ内容を求めるというのは、その辺はどうなっているのでしょう。その辺の相談を受けたり代替保育を実施したりする側の体制整備というのはどのようになっているのか尋ねました。","respondent":"竹田保育課長","answer":"そもそも小規模保育施設には、区の独自加算で代替要員の費用が支給されておりますので、私立の認可保育園は代替保育は求めないというのが基本です。ただ、いろいろなケースが考えられますので、そういった場合は公立を中心に受け入れていくということを今考えております。","id":"exchange-007"},{"speaker":"あべ委員","kind":"確認","question":"資料の２のところで、国ではこう示しているけれども基本的にはこれまでどおり小規模保育の中で運用してもらうということでよろしいのでしょうか。それから、(2)の保育内容の支援については、基本的には公立のほうで対応するというお考えということでよろしいか尋ねました。","respondent":"竹田保育課長","answer":"家庭的保育事業については今までも急な病気等で近隣の公立園で受け入れたという実績もありますので、このようにしていく考えです。それから、相談、助言等ですが、こちらについては新しい制度ですので、今後協定書も結びますので、徐々に深めていきたいと考えております。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３歳から希望される方もいらっしゃるので、ぜひ情報をしっかりと伝えて、ぜひそこのところは工夫をしていただきたい。ちょっとそこを確認させていただきたいのが１点と、３のところの(1)の1)の巡回指導という、現在行われているこの中身をちょっと説明を求めました。","respondent":"竹田保育課長","answer":"来年３月の定員枠は２８０人ですので、全体で考えれば認証保育所の卒園児も区内で受け入れられる体制はできているところです。巡回指導ですが、あるいは保育課の保育士等が巡回しまして、具体的に改善点とかをお話しさせていただいて保育の参考にしていただいているところです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この連携園の表のところでは、困難な人というのは、先ほど伺った通常の選考になるということですか。そのことを１点、お伺いします。","respondent":"竹田保育課長","answer":"こちらの連携園以外をご希望なさっている方については、現在認可園にいる方が転園を希望するのと同じように選考になります。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"そうなった場合に、そこら辺は人数的にそれが確保できないというようなことなのでしょうか。もう少し教えてほしいと求めました。","respondent":"竹田保育課長","answer":"１、５歳になってから転園ということもありますので、そういった状況を踏まえながら連携施設を設定していきたいと考えております。全体の枠として受け入れられるように、できるように努力してまいります。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこはぜひ行く先がないというようなことがないようにご検討いただきたいのと、この施設はやはり国が求めているものということですけれども、認証においてもまたこれからの運用の中でしっかりと、品川区として一歩進んだ運用の仕方をぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問","question":"認証を出た３歳の方が幼稚園に行かない限り、議論になったように入れないというのは、今年の数字からするともう明らかなのです。どうしましょうかというお話が幾つか出ているのですけれども、相談、協議するとかということについては何かあるのか尋ねました。","respondent":"大澤待機児童対策担当課長、竹田保育課長","answer":"新規開設につきましては、平成２９年度についても多いところでは６名の差をつけてくださっている新規事業者もいらっしゃいますので、そういった意味では今後の新規開設ではかなりそこの差分は増えていくということはあります。 東京都への申し入れですが、機会を捉えて適宜申し入れていきたいと考えています。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"どういうことを言ったらいいのでしょうか、すみません、具体的に。どのような方策がというところはなかなか難しくて余り思いつかないので。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"毎月２３区の課長会等で東京都の担当の方が説明にいらっしゃってお会いする場面があります。そういう場あるいは機会に区としての、自治体としての意見も述べさせていただきたいと思います。 そういった場面の中では、特に３歳児の壁という問題が大きいことだということでお伝えもしてありますし、一番大事なのは新規開設なのですね。…","id":"exchange-014"}]},{"id":"topic-02","title":"を引き続き聴取いたします。 (2)八潮地区幼保一体施設の定員","agenda":"を引き続き聴取いたします。 (2)八潮地区幼保一体施設の定員","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"これは拝見すると平成３１年の４月から新しい幼保一体移設ができると０歳児は３人、３歳児は２名減るということなのですよね。それは結局遊戯室の広さを現状のままで確保するのでスペースがとれないということでよろしいのか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"保護者、地元住民等の要望から、現状の遊戯室の広さを確保してほしいという要望がありましたので、遊戯室をつぶさないと限られたスペースになりまして、最大限入れましても０歳児、３歳児に関しては３名と２名の減になってしまいます。","id":"exchange-015"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、結局この保育園は現実として数が減ることになると思うのですけれども、ただ八潮というのは要するに人口が減っていますよね。そうすると、利用している方というのは八潮のエリア以外からも結局たくさん越境というか、わざわざ来て入園されている方というのは結構いるのか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"八潮の保育園の在園者の住所の関係ですが、八潮地区に住んでいる方が約５３％、八潮以外の方が約４７％で、ほぼ半分半分の状況です。","id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、八潮が減った分、今の課長のご説明ですと、八潮北と西と中央の受け入れの弾力化を検討するということは、足りなくなった分はほかの近隣の保育園で吸収できるというふうに考えればいいのか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"八潮については施設が比較的広く整備されていますので、人員配置等を行った上で１園当たり０歳児１から２名の受け入れは可能と考えております。八潮北・西・中央の大規模改修時に、状況によって定員の拡大等も検討したいと考えております。","id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それとあと、人数が減った分に関しては、ただ近隣から来ている方も多いので、近隣の保育園を弾力的に定員拡大することによって十分吸収できると。そうすると、とりあえず余り大きな利用者のご負担はない状態で新しい施設ができるというふうにお考えだと理解してよろしいか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"委員ご指摘のとおり、在園者の約半数の方が八潮地区外から通っている状況ですので、まず勝島・東大井地区の民間保育園等の整備を進めます。先ほどご説明させていただきました八潮地区内の保育園の定員の拡大を図っていければ…","id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"行き先がなくなってしまったということがないように、丁寧にご説明をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"それが終わった後、八潮南のところはどうしていくのか、お考えがあれば伺いたいと思います。やはり保育園などにしていっていただきたいと思うのですけれども、今のお考えを伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"５歳というふうな形にしたほうが幼稚園・保育園の一体的な運営ができるということで、十数パターン、両方の園長を入れていろいろ検討しました。平成３３年度まで八潮北・西・中央保育園の改修で使いますので、その時点でまた活用については検討していきたいと考えております。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"今、この八潮わかば幼稚園の敷地・建物というのは幼稚園で使っていらっしゃるということなのですが、実際の在籍者数というのは今どれくらいか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"八潮わかば幼稚園の在園者の状況なのですけれども、４月１日の時点で４歳児が２５名、５歳児が２８名です。","id":"exchange-021"},{"speaker":"あべ委員","kind":"確認","question":"保育士の事務室等々を含めてかなりこれまでと敷地の感覚といったらいいのですかね、保育士、何か増築なんかを図る部分はあるのでしたか。ちょっと確認したいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"職員の休憩室とあと幼保一体施設ですので、地域の子育て支援施設ということで、倉庫の部分をつぶして一時相談室みたいなものをつくります。そういうのも全部入れて、あと施設の広さの基準等もクリアした上で、この定員です。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"それが１つとても残念だなと思っているのと、あと４の（１）のところの定員減の対応ということで、これはいつの時点からになるのでしょうか。ちょっとその辺についての考え方と、これもちょっと具体的にどのような考えで進めていくのか説明を求めました。","respondent":"佐藤保育施設調整担当課長、大澤待機児童対策担当課長","answer":"１点目の定員が変わらないようにということは、実施設計中ですのでどうなるかわかりませんという回答を私はさせていただいたと考えております。弾力化の開始時期ですが、平成３１年４月から定員が減りますので… 東大井と勝島につきましては、平成２９年に２園新規開設、また平成３０年に今区民公園が決まっておりますので、そちらのほうにも開設予定があります。平成３１年の開設について、今のところまだ未定という状況です。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なので、極力本当に弾力化ではなく、定数の拡大とかやむを得ないときはそういう形でやっていただきたいなと思っています。決して１１０％をよしとしないでいただきたいと思うのですが、いかがか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"弾力化の関係ですが、園の運営の安全面を重視して園運営が十分可能な範囲で行っておりますので、何も詰め込んでいるという認識はございません。申請者の状況もありますので、その辺を総合的に見て、バランスよく安全面に配慮して行っていきたいと考えております。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"弾力化のところは、特に本当に安全面は当然です。そこの職員の方が一番よくわかっていらっしゃるので、園長先生だけではなく、働いている皆さんの意見をきちんと聞いていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つだけお尋ねするのですが、この幼保一体型の施設は、旧来品川区にある幼保連携並列型の形をとることになるのでしょうか。以前にもちょっと質問したときに、進めていくつもりはないというようなお話を伺ったのですが、今後もその方針に変わりはないか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"認定こども園の対応ですが、私立の認定こども園化については今後も区として支援を進めます。５年間の経過措置はありますけれども、そのような課題については２３区全体で検討しておりますので、その辺の推移を見ていきたいと考えております。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"進めてバックアップをしていっていただきたいのと、ぜひほかの自治体とも協力して方策を考えていってほしいと求めました。この点については別の機会にまたお伺いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問・要望","question":"ちょっと先ほどの数字を確認させていただきたいのですけれども、今八潮以外から来られている方が４７％ということで、東大井の範囲なのでしょうか。多く来られているエリアの中で、来年度、再来年度に新規開設する園の定員はどのくらい増えるのかというのをお伺いしたいのですけれども。","respondent":"佐藤保育施設調整担当課長、大澤待機児童対策担当課長","answer":"八潮の保育園に通っている方の八潮以外の住所の割合ですが、東大井で約１０％、東品川が７.７％、南大井が５.１％です。人数としては、東大井が４３名、東品川が３２名、南大井が２１名、あと大井と南品川が数名の状況です。 平成２９年の勝島と東大井の定員増ですが、１３７名を予定しています。","id":"exchange-028"}]},{"id":"topic-03","title":"平成２９年度入学希望申請の状況","agenda":"平成２９年度入学希望申請の状況","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"昨年もお聞きしたと思うのですけれども、毎年１５０名前後だったのが、増まで減っているので。これを見ると荏原第一中学校と、こういう全体の不人気校というのに関して教育委員会としてやはり何か取り組みとか精力的になされているのか尋ねました。","respondent":"有馬学務課長","answer":"去年ベースでいくと、この２１と８を足すと２９ということですので、そういう意味で言えば、傾向としては同じというふうに考えています。特に、特にここはそういう要因を抱えているために減が多くなっているということが一つの要素として考えられると思っているところです。","id":"exchange-029"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、教育委員会としては、これを学校の区割りの問題がメインでこういうアンバランスになっているというふうに考えていると理解してよろしいか尋ねました。","respondent":"有馬学務課長","answer":"学区割りが全てとは考えておりませんけれども、特にこの荏原平塚学園につきましては、そういう傾向が一番強いところとは認識しております。荏原平塚学園も学校説明会等を行って、また今後検討していきたいと思いますけれども、一番のネックとなっているところは。","id":"exchange-030"},{"speaker":"新妻委員","kind":"質問","question":"希望申請数のところなのですけれども、小学校、義務教育学校も中学校も平成２７年度から自分のエリア外のところに希望する人の割合が減ってきていると思うのですが、この傾向をどのように認識をされているのかちょっとお伺いしたいと思います。","respondent":"有馬学務課長","answer":"この間７.３％落ちてきているということで、これはでこぼこではなくてずっと徐々に下がってきているとまず認識をしております。自分たちの学校にぜひ来てくださいということが少しずつ浸透してきた結果ではないかと見ているところです。","id":"exchange-031"},{"speaker":"新妻委員","kind":"質問","question":"これは逆にいい傾向であるという認識をされているということですかね。","respondent":"有馬学務課長","answer":"これは当然学校がそれぞれ競争していきながらということもありながら、そういう各学校が切磋琢磨しながら住民に地元の学校を選んでもらえるということはとてもいいことだと考えております。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問","question":"人口が増えていて学校の対応をこれから見直していかなければいけないなという地域があるかどうか、それが１点と、大丈夫だよというところを説明を求めました。","respondent":"有馬学務課長","answer":"建築や開発を所管する部署のほうから、大きければ再開発地域もありますけれども、それ以外のところでも情報をとりながら人口推計をしているです。これは例年の傾向ですが、３割程度が私立に抜けるというようなこともございまして…","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"今、３割ぐらい私立にということなのですけれども、私立を選択する傾向というのは余りこの間変わりないのでしょうか、推移として。","respondent":"有馬学務課長","answer":"この間、小学校のほうについては６％程度、中学校につきましても大体３０％程度というようなことで、大きな変更はありませんので、来年度についても大体大まかにいえばそのような数字で推移するものと考えています。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"こういった学校では、例えば御殿山なんかを見ると、外に出ることを希望している方が全員出ていってもまだ受け入れ枠に収容し切れないわけですよね。こういうのは、まさか外に出ていくことを希望されない方まで外に出ることはないと思うのですが、どのように対処されているのか尋ねました。","respondent":"有馬学務課長","answer":"この中から、もしそのまま９０名を超えた場合については当然通学区域内の児童生徒ということですので、これは必ず受け入れをすると。希望される４５名についてはなかなか厳しいところがあろうかと思いますけれども、これまでと同じようにしっかり受け入れをしていくです。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"例えば転入などで増えていった場合、かなりぎりぎりの状態なので、数が足りなくなるケースは今のところは出ていないのでしょうか。今後かなりぎりぎりなところが幾つか出てくるのではないかと思うのですけれども、その際はどういうふうに対応されるつもりか尋ねました。","respondent":"有馬学務課長","answer":"本来は３５人学級ですから、それを超えた場合は１クラス増やさなければいけないというような形が原則的には出てきます。そういった場合は、直前になってそういうことがないように、１年先を見ながらその辺はきちんと対応していっているです。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問","question":"１０人以上差があるところというのも３分の１ぐらいあって、かなりのところで毎年厳しい運用をしていると。ここまでぎりぎりの数字の中で運用されると、選択制そのものの性格が変わってきていると捉えたことはないのですか、教育委員会としては。","respondent":"有馬学務課長","answer":"ただ、あくまでまだ学校改築との兼ね合いも出てきます。これから始める学事制度審議会の中でもご議論をいただいて、ある程度の方向性を出していければと思っているところです。","id":"exchange-037"},{"speaker":"あべ委員","kind":"意見","question":"学校選択制の議論をこれからしていくと思うのですけれども、多分この制度を今現実的に一番考えているのは区と教育委員会だと思うのですね。これがないと、その辺を議論されるいろいろな方にご理解をいただくというか…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"確認","question":"つまり、１番が今これを見ていたら城南になっているので、今後そういった学校番号で運用していくように進められていくのでしょうか。ご兄弟で待機となられた学校がどれだけあったかということの確認だけしたいと思います。","respondent":"有馬学務課長","answer":"全員待機の方が５校で２１名です。ほかの２校につきましては、１０人のうち半分の５名が待機ということですので、合計兄弟枠での待機は２６名となっています。","id":"exchange-039"},{"speaker":"高橋（し）委員","kind":"質問","question":"さっきちょっと言い忘れたのですけれども、すみません、１つだけ。品川学園ですか、その辺についてどのような要因というか、もしありましたらお願いいたします。","respondent":"有馬学務課長","answer":"次が小山台小学校、これが２年ぶりですけれども、住基人口がやはり１９名増えています。その差をあらわすと１３名というような影響が出たというようなことで、少し地元のところがニーズが増えてきているのかなと思ってあります。","id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"意見","question":"数字的に１桁ぐらいの住基人口が増えたとしてもこうやって抽選になったり、もともとぎりぎりというかいっぱい入るまで地域の方が移動していたという認識でよろしいですね、ありがとうありますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"}]},{"id":"topic-04","title":"平成２９年度品川区立学校教育職員採用候補者選考の結果","agenda":"平成２９年度品川区立学校教育職員採用候補者選考の結果","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"もともと採用予定の人数とかというのは決まっていたのか尋ねました。","respondent":"熊谷指導課長","answer":"採用予定人数は６名程度ということで考えておりました。","id":"exchange-042"},{"speaker":"鈴木（博）委員","kind":"質問","question":"さらに面接試験と３回の試験をくぐってきて、それでこの人はすばらしいだろうと思うような方を６名、結局１名辞退があったということですよね。これは例えば補欠で繰り上がりだとか、何かもしも抜けた場合補充するような手立てとかというようなご検討はされているのか尋ねました。","respondent":"熊谷指導課長","answer":"この第２次選考のときに１２名おりますけれども、この１２名については名簿登載というふうになっております。６名程度となっておりますので、今年度についてはこの５名でやっていきたいということで、今回は５名を採用したところです。","id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、例えば欠員が出た場合に、補充するとかというようなことをあらかじめ想定したお考えとかはないのでしょうか。それとも、そのときはまたそのときで減った人数で今年はこれでいきますということになるのか。","respondent":"熊谷指導課長","answer":"先ほどの名簿登載者１２名ですけれども、実際に名簿登載しておりますので、補欠繰り上げということも考えておりました。ただし、今年に関しては、特段５名で、繰り上げなくてもよいと判断いたしましたが、必要に応じて繰り上げるということももちろん想定しています。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"こんなことを伺っていいのか、逆に辞退されなかったというか、それでも区を選んだということなのか。その辺の状況を教えていただけばと思います。","respondent":"熊谷指導課長","answer":"実はそうしたこともありまして、実際に小学校の教員養成課程がない大学にも１５校ほど人事係が回りまして、そこで説明をしてきた経緯があります。説明会の満足度というのもありまして、実際に３４名が出席されましたけれども…","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"経験があって受験をして受かった方が何人くらいいらっしゃるのかお聞きしたいのと、あと、今回はどんな傾向だったのか。区内の方がどのくらい合格者の中にいらっしゃるのかなということをお聞きしたいと思います。","respondent":"熊谷指導課長","answer":"現在１９名おりますけれども、経験があった方は１１名です。採用の方ですけれども、採用の方は、品川区の方は残念ながらいらっしゃいません。","id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"質問","question":"合格した６名の方で、結局合格したのは中学校の保健の方２人で、あともう一人は特別支援のほうで。受験生の身からするとそういった部分を気にされることもあるのではないかと思うのですが、その辺はいかがか尋ねました。","respondent":"熊谷指導課長","answer":"品川区での経験がある方ということですが、経験者の１名ですけれども、現在も品川区で産休代替をやっていらっしゃる方であります。それから、それにつきましても説明会等、本当に教員の採用試験の適正な選考過程に基づいて実施しているということを改めて伝えていきたいと考えま…","id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"意見","question":"それはもちろんいろいろな理由の中の１つなのでしょうけれども、いいと思いますので、そういった方がたくさん受験されることを期待したいと思います。ご説明いただくということで、ぜひ受ける方々にそういったところは…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"この先どういうふうに固有教員の制度を、毎年５名ずつ採用していけばどんどん増えていくわけで、正直言って。やはり都にも求めることは求めていかないといけないのかなと思うのですが、どういうふうに考えられて進められていくのか、説明を求めました。","respondent":"熊谷指導課長","answer":"中学校９校と義務教育学校６校を含めたいわゆる各中学校区に２名ずつ合計３０名を目途に計画的に採用していく予定で考えております。現段階では３０名が上限ということで、これからあと２年間ありますので、適正な採用を行っていきたいと考えています。","id":"exchange-049"},{"speaker":"沢田副委員長","kind":"質問","question":"平成３０年まででこの固有教員の制度の採用はこの先はとりあえずしないという形なのか尋ねました。","respondent":"熊谷指導課長","answer":"現在のところは平成３０年を目途にということで、これで一旦固有教員についてはこれ以上は採用しないということで考えております。","id":"exchange-050"},{"speaker":"沢田副委員長","kind":"質問","question":"今度はやはり役職がついてくれば下の固有教員の方がいなくなっていきますが、またそのときはそのときで採用を考えていくということなのですか。そのときによってということか尋ねました。","respondent":"熊谷指導課長","answer":"平成３０年というのが目標で目途に考えておりますけれども、あと将来的にはやはり退職ということもありますので、継続してまた時期を見て検討していきたいと考えます。","id":"exchange-051"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"ちょっとこのプレパパのところに力を入れていただいて、力を入れていただきたいので、それはいかがでしょうかということ。子育て交流サロンは今３カ所やっていて、時々意見も寄せていただいているのですが、これは今後の展開としてどのような感じなのか尋ねました。","respondent":"高山子ども育成課長、廣田子ども家庭支援課長","answer":"まず１つ目が、いわゆる親育ち支援事業のネーミングに係る部分なのですが、特にそういったものを強いているといった認識はございません。そういった思いはありますので、そういった２カ所目の事業の充実も含めながら… ひとり親の医療証を交付されているのが１,８３７世帯で、それぞれ要件が若干違うので、そういった数字になっています。３,９３０世帯というところなので、ある一定所得以下の世帯は２,５００世帯ぐらいというところでは…","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問","question":"そのうち２,５００世帯ぐらいが経済的に厳しいといいますか、決して楽ではない生活をしているというような大体のイメージでよろしいでしょうか。この配慮というのはどのような形があり得ると現段階で検討されているのか尋ねました。","respondent":"高山子ども育成課長、廣田子ども家庭支援課長","answer":"先ほども申しましたように、そのように誤解を招くようであれば、ちょっとこの辺の表現については再度検討させていただきたいと思います。こうした施設における魅力創出を… 共働きであったり孤食もそうですけれども、それも全て検討していこうというところで、学習支援なら学習支援でいろいろな環境にある子というところで。孤食についても、孤食だけではなくて…","id":"exchange-053"},{"speaker":"あべ委員","kind":"質問","question":"それで金融系の資格を取って、それから生活保護を外して正社員として働き始めて、１年ではないな、２年ぐらいですかね。ただ、それを支えるためには、行政としてはそういうことというのは標準的に対応が可能なのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"働けない状態であれば、ひまわり荘に入ってもらってある程度負担を減らして子どももある程度手助けしてあげてというような支援もしているところなので、その状況に合わせた支援を相談員が的確にできるようにということをスキルアップしていくことが大事かなと考えております。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"ひとり親家庭の方の把握が難しいという中でも、児童育成手当受給者の調査で、やはりこれを受けていない方もいらっしゃるという考えでいいですか。漏れている方もいろいろ含めて２,５００世帯ぐらいになってくるということでいいのか、改めて確認させてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"それ以上だから支援が要らないとも思っているわけではないのですが、この一定所得以下の人はいるよという認識で、施策を考えていくという認識です。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問","question":"今まだ検討中ということですが、現在の検討の中で出てきた課題があれば伺いたいと思います。そして、この分科会の中では今回出された４つのカテゴリーで分かれて検討されているということか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"今回ひとり親の話をさせていただいたのですが、課題については１枚目で触れさせていただいているような内容で整理しております。学習支援、親の就労支援、今検討としては５つのカテゴリーで検討しています。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういった中でやはりこの間求めておりますのは就学援助をやはりこういったひとり親家庭の方が受けてやられていると思うのですけれども、この間もずっと求めてきましたけれども、果たして実施していくお考えはあるのか伺いたいと思います。","respondent":"有馬学務課長、廣田子ども家庭支援課長","answer":"現行の制度で申し上げますと、前年度の収入をもって認定していくということですので、なかなか前倒しが難しいというふうな見解に立っているところです。 区として奨学金をどうしていくかというのを考えていきつつ、迅速に対応できるようにというところで今検討しているところなので、現在どうこうするというところについてはちょっと言及できるような段階にはないと考えております。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"決算特別委員会では財調でこれは立てるという話だったのですかね、そういったお考えがあるのか伺いたいと思います。３万円で十分だと区で考えていらっしゃるのか、さらに増額等求めていく考えはあるのか伺いたいと思います。","respondent":"有馬学務課長、廣田子ども家庭支援課長","answer":"就学援助については、その財源は財調である程度補填されておりますけれども、財調そのものが性質的には一般財源ですので、そもそも一般財源を投入しているです。 国の３万円というのも、東京都も今いろいろ考えて動いているところなので、区でどういう役割分担をするのかということを整理してからどうするかということを検討する必要があると考えています。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ実施に向けて積極的にやっていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この事業を教えてほしいのと、ちょっとその点を１点お答えいただきたいのと、あとたくさんの資料をありがとうあります。ちょっと余り質問になっていないと思うのですが、その辺にお考えがあったら聞かせてほしいと求めました。","respondent":"高山子ども育成課長、廣田子ども家庭支援課長","answer":"こうした事業を平成１７年度からサンデー子育てサポート事業を進めてまいりました。こういった６館の利用の定着を見ながら、ご指摘の点につきましては必要性については検討してまいりたいと考えています。 第３子３,０００円と定額だったのですが、満額では１万円、第３子についても満額で６,０００円という形で改善されつつあります。２カ月、３カ月に縮まるだけでも大分暮らしやすくなるのかなというようなところで…","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域でお子さん３人持っているお母さんが、すごく一生懸命働いているのだけれども、やはりすごく子ども３人で厳しいと。でも、こういう事例に対して援助が少ないですよねというお話をたびたび伺っているので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"新妻委員","kind":"質問・要望","question":"子育てをされている世代のお父さん、お母さんが子育てに悩んだときにまずどこに相談をするのかというのは、どこでまず確認ができるのでしょうか。まず、そこがどういうふうに、ではそれはどうやって周知をしているのかというところを一つ確認をさせてください。","respondent":"高山子ども育成課長","answer":"あるいはこの４月から子育て応援アプリということで、こういった相談の仕組みの周知などもあわせて図っているところです。それから、区内大学の連携という点につきましては、日帰り型の産後ケア事業について実施していると伺っております。","id":"exchange-062"},{"speaker":"新妻委員","kind":"質問・要望","question":"そういう何かあったらそこに電話したら全てのところにつながっていくのだというような、ワンストップで対応できるような窓口という、わかりやすい場があるといいなということを要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"高橋（し）委員","kind":"質問","question":"働きというのはどういうふうになっていくのかなというところで、そこと児童センターとのかかわりをお尋ねしたいというのが一つ。この調査結果ですか、結果が全部出た年度の終わりではなくて、どういう感じで伝わってそれが活用されるのか尋ねました。","respondent":"高山子ども育成課長、有馬学務課長","answer":"連携の仕組みとしての要保護児童対策地域協議会、１３地域については今後も児童センターにおける一つの機能として存続していくのだと考えております。児童センターは築４０年を超える建築物も増えて… これにつきましては、まず校長会のほうにこのアンケートを流しまして、実態を見ていただいているです。これから、そこまではまだ進んでいませんので、正式なコメントということではまだここでは申し上げられないです。","id":"exchange-064"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ネウボラを導入されたということですので、児童センターの役割はますます重要になると思いますので、また検討を進めていってほしいと求めました。教育委員会のほうのプロジェクトの中でぜひ教育委員会としてのお立場で改善策というかそういうものを積極的にお話ししてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"質問","question":"大学とか産婦人科の中でつながってきているのですけれども、小児科とはつながらないのですか。要するに小児科あるいは小児科医会とつながるとか、コンタクトは全然ないのだけれども、そういう仕組みというのはあるのか尋ねました。","respondent":"高山子ども育成課長","answer":"庁内的な連携もそうなのですが、そういったさらなる事業展開というのは今後も広げていくように考えてまいりますので、ご提案の部分につきましてはチャンスを捉えてネットワーク事業のほうに参画していただけるよう働きかけてまいります。","id":"exchange-066"},{"speaker":"あべ委員","kind":"質問・要望","question":"養育費がないのが当たり前というのではない状況に区としても頑張っていただきたいなと思いますが、その辺のお考えをまず聞きたいと思います。どのようなサービス、選択肢があるのか、ここも教えてほしいと求めました。","respondent":"高山子ども育成課長、廣田子ども家庭支援課長、齋藤子ども未来部長","answer":"決して多くはないですが、そういったものができるだけ継続的に進められるようなご案内などはこれまでもしています。いわゆる情報提供… 育成についてこれからというかもう既にですけれども取り組んで、相談員をもうちょっと強化していきたいなと思っているところです。… 養育費の相談はなかなか難しいところがございまして、うちの相談員で家庭裁判所の調査官をされた方がいらっしゃいます。そういったものを見きわめながら…","id":"exchange-067"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ力を入れていただきたいのと、国の動向を見るだけではなくて、やはり声を都に対して、国に対していろいろな機会で上げてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"沢田副委員長","kind":"質問","question":"先ほどあべ委員の質問の中でちょっとあったのですけれども、在宅での子育て支援をやはりより充実していったほうがいいのではないかと思います。何ていうのですかね、どうしても仕事をせざるを得なくて働いている方たちに対してよりも、そのあたりの考えというのはどうなのでしょう。","respondent":"齋藤子ども未来部長","answer":"もう一方で、８５０万円以上かかるという中で、在宅で育てるより保育園に預けたほうがもしかしたら得かもしれないという意識もやはりなくはない。やはりご支援をすることも大切だと私ども思っておりまして、どういったあり方で家庭で育てる方を支援するかというのは、来年。","id":"exchange-069"},{"speaker":"沢田副委員長","kind":"質問","question":"世の中が変わってきてこの１０年ぐらいでそういうふうになってきているのだと思うので、ただこれだけが唯一の道ではないと思うのです。決して財政的に予算的に厳しくなるとかではなく、保育園にかかっている分がそっちに行くわけですから、ぜひ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"}]},{"id":"topic-06","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"のだて委員","kind":"提案","question":"区も調査しているということで、この間の経過と課題、抜本的な改善策の提案はあるべきだと思います。報告書の提出はしないとの答弁でしたけれども、提出しない理由を伺いますとの意見を述べました。","respondent":"竹田保育課長","answer":"１２日の計３回保護者説明会において補助金を不正流用するなどの事業者を選んだこと、保護者の皆様に意を尽くして説明させていただきました。それから、看護師の不配置についてですが、年度末に委託料の精算を予定しております。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問・要望","question":"精算すればいいということなのか伺いたいと思います。報告書の提出については、調査中ということなので、そうすると調査し終わった後に報告書を提出していただけるということか尋ねました。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"引き続き配置を求めてまいります。調査報告の内容を議会、保護者の方にご説明しておりまして、区としては報告書を提出する考えはございません。 １つ目の債務不履行で看護師がついていないのは確かによくありません。おおむねの回答ができましたら、当委員会でご報告いたします。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問","question":"やはり今回の問題は保育園の事業者がかわる、保育士がかわるという重大事態ですから、文書にまとめて提出するべきだと思います。伺います。","respondent":"竹田保育課長","answer":"看護師については、委託契約の不履行と考えておりますので、履行に向けて今後も申し入れてまいります。前回の委員会の報告の中でも、ご説明した資料に一定程度入れさせていただいたものです。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"報告書のところでは、前回報告したというお話ですけれども、それは兵庫県の報告書にはこうありましたという報告だったと思うのですね。どうしてこういったことが起きたのかということをまとめるべきだと思うのですけれども、いかがでしょうかということです。","respondent":"齋藤子ども未来部長","answer":"２つあって、１つは調査に関することなのですが、私たちは委託業者として委託業務契約に関することでは調査応諾を求めることができます。報告書自体は法に基づいてできるものと、委託契約に基づいてできることは違いがあるので、ご理解いただければと考えています。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、報告書の件は今の品川区の契約等のやり方では、法的には報告書はできないということか尋ねました。","respondent":"齋藤子ども未来部長","answer":"それは意を尽くしてご説明したということしか言えなくて、何を謝罪しろと言っているかが明確ではなかったので。こういう説明がなかっただとか、印象を受けたというふうに聞いている、伝聞です。","id":"exchange-075"},{"speaker":"あべ委員","kind":"質問","question":"品川区は、今後の保育園に限らずこういった不正な請求の防止策あるいは歯どめというようなものというのは、区として何かお考えなのか。そういったものも活用しながら、領収書さえあればいいということでは行政として困るのではないかと思うのですけれども、どのようにお考えか尋ねました。","respondent":"齋藤子ども未来部長","answer":"具体的に言うと、うちもいろいろ調べたのですけれども、それが適正かどうかということを判断することはなかなか難しい部分もあります。今日この場ではお話しできませんけれども、いろいろ調べもしている部分がありますので、それは追ってご説明させていただければと思います。","id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問・要望","question":"質問の繰り返しになるかならないかは、質問にきちんと答えてくださっているかどうかにかかっていて、やはり不十分であるので足りませんよという意味でフォローさせていただいているので、その点はご理解ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問・要望","question":"既に調査していますということなので、ぜひそこの認可保育園の需要調査を求めていますので、ここについて出してほしいと思ったのが質問３です。質問５のところは、この支援が前に進むのかどうか、再度お尋ねをしたいと思って質問に入れました。","respondent":"大澤待機児童対策担当課長","answer":"検査指導の強化につきましては、東京都と連携して適切な指導検査をしてまいります。ほかの議員からも決算特別委員会の総括質疑の際にご質問がありましたが、保護者の負担のあり方については、今後別途検討してまいります。","id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと質問２のところだけ。何ていうのですか、区がやはりそういった対応ができていないことへのお答えを求めたのですが、その点はいかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"何度も申し上げているとおり、計画上では推計上では解消できるほどの認可保育園の開設は平成２９年に予定しております。私どもは、それに沿って計画以上の開設をしておりますし、今後もゼロを目指して開設について努力してまいります。","id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり間に合わせようと思うのであれば、やはり間に合っていない現状についての点検とか反省がない限り、次に行かないと思うのです。ぜひその点を検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/462438?Template=document&Id=4902#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":70398,"voices":206}},{"id":"h28-20161129-5","meetingId":"h28-cm11","date":"2016年11月29日","dateIso":"2016-11-29","committee":"総務委員会","time":"午前１０時００分～午後 ４時５６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"第９４号議案、平成２８年度品川区一般会計補正予算","agenda":"第９４号議案、平成２８年度品川区一般会計補正予算","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"もちろん事業所を通してでしょうけれども、例えば多くの方が私も助成を受けたいと、増えた場合はどういうふうに対応されるのですか。予算は予算で計上されていますけれども、追加で出た場合には追加計上していくのか尋ねました。","respondent":"秋山財政課長","answer":"増える対象は、これはまだ想定ではありますけれども、あと１０人ぐらいではないかと所管から聞いているところです。予算がなくなったからといってお支払いをしないということではなくて、その他の事業との具合を見ながら、追加でお支払いすることになるかと思います。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問・要望","question":"そうするとまた、区立もそうですけれども、私立保育園の保育士の皆さんも相当助かる。保育士にも、こういうものがありますよという普及啓発に力を入れてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"吉田委員","kind":"確認","question":"ほかの委員会で審査をされた分については、なるほどと私も納得するところなのですけれども、やはり昨日の……、ごめんなさい、確認をさせてください。どういうところに急なお金が必要になったかのヒアリングとかをされての積算なのか、その辺を伺いたいと思うのですが、いかがか尋ねました。","respondent":"秋山財政課長","answer":"今回の補正予算で出した１５億円というのは繰越金からの１５億円ということですので、それをどう使うかというのは、当初予算でこちらからご提案をする予定ですので、具体的にどういう形で使うというのは、今後、検討していくです。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"それで、推定していくしかないと思うのですけれども、今まで震災が起きているところは割と生産県ではないですか。もう間がないわけですから、それとも一般財源から出すべきだというような、その辺についても説明を求めました。","respondent":"秋山財政課長","answer":"そういう中で具体的に何が必要かというのは、当初予算を立てるときに、それをベースにつくったものをご提案する予定でおります。災害が発生した場合の支出については特別会計を使って、使うときの財源は改めて補正予算でご議決いただく形になります。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"はとにかく特別会計をつくって、財源にこの基金を充てていって、今決めるのは繰越金の中からまずは１５億円を最初に積んでおく。それはやっぱり繰り越しがあったからという感じで捉えてよろしいのか尋ねました。","respondent":"秋山財政課長","answer":"話の最初のスイッチというのはやはりこれが必要ですというところで特別会計や何かを組み立てたわけなのですけれども、ただ、その財源はどうするかと考えたときに、今使える繰越金が１５億円ありますというので、１５億円を今回ご提案させていただいたです。","id":"exchange-005"},{"speaker":"南委員","kind":"意見","question":"防災対策費として基金に１５億円の積み立てをするというこの問題については、そうであってはならないし、やめるべきだと考えています。それで反対をしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"この基金の考え方自体についてはこれからも当初予算でいろいろな議論を積み上げていくべきだと思いますので、必要性は私たちは感じております。疑問は残しながら、額としてはこれくらいは必要なのではないかと判断して、賛成いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"新地方公会計制度に基づく財務４表","agenda":"新地方公会計制度に基づく財務４表","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"「５.公表について」なのですけれども、１２月２１日というのはどの段階が公表されるか、教えていただけますか。","respondent":"秋山財政課長","answer":"これは平成２７年度の決算です。平成２７年度の決算の記事の中で、今回ご報告させていただいている財務４表は平成２７年度のものですので、それを公表することになります。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"そのときもこのタイミングは変わらないのでしょうか。それとも今後は新しい公会計制度に基づいて変わっていくのか、その辺を説明を求めました。","respondent":"秋山財政課長","answer":"決算統計といって国が４月末に確定した数字をもとにつくっておりますので、出納閉鎖後に財務４表は出るという形で予定しており、この時期よりももっと早目にご報告ができるようになると考えています。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"どんなふうに見ていったらいいのかというのを教えていただきたいなと思うのが１つと、あるいは出えん金を出している団体がほかにもあると思うのです。それがどのくらい、どういう団体があるのかという全体の姿を知りたいなと考えています。","respondent":"秋山財政課長","answer":"財務４表をつくるというのは、財務４表を見ただけで、そちらで見ていただくというのが通常の使い方ではないのかと考えています。これ以外に、手元にありませんので、申し訳ありません。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"言ってもどうしようもないのですけれども、しかし、そういう予算を組んでいただきたいということもあわせて言っておきたいなと思います。〔「決算書に出ているよな」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"その資料を提供していただきたいなと。ということも含めて、説明を求めました。","respondent":"秋山財政課長","answer":"決算委員会の資料として出している決算書の中に、区が出資している団体の一覧がありますので、そちらを確認すれば出ております。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"その発端になった意識というのが、この前の一般質問で取り上げた東京熱供給株式会社に２％出資しているのですよね。ですから、そういう類いのものがどのぐらいあるのかなというのを知りたくて質問したのですけれども、決算書に出ているということですよね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"}]},{"id":"topic-03","title":"品川区公式ホームページのトップページリニューアル","agenda":"品川区公式ホームページのトップページリニューアル","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"まだ１カ月たっていないですけれども、どのぐらいアクセスがあるのか教えていただきたいのと、「いいね！」とかコメントとか、そういったところはこれからということで、考えとしてはあるかどうかというのを教えてほしいと求めました。","respondent":"中島企画部副参事、中元広報広聴課長","answer":"シティプロモーション動画の再生回数についてのお問い合わせですが、昨日カウントいたしましたところ、２本あるうちのまずはお祭り編につきましては約１,４００回、商店街編については約１,０００回の再生回数がございました。 こちらもフェイスブックを初めて導入いたしますので、まずは記事アップを心がけ、今後、ご提案のありましたように、「いいね！」機能とか、そういうものを使いながら…","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問","question":"自分でもやったのですが、なかなかアクセスしないところが課題かなと思っているのですが、そうしたところは今後どういうふうにしていくのかなというところを説明を求めました。","respondent":"中元広報広聴課長","answer":"品川区公式ユーチューブは、実は１２月１９日目途で今準備をしておりまして、それで今、ユーチューブでは、「不動麗子」で検索をしていただくと比較的上段に出てまいります。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"これからだというところで承知しましたが、「不動麗子」で検索は知らないとできないですよね。これは「しながわネットＴＶ」で検索するのか、「品川区」とかで検索するとぱっと出るようになるように工夫されているのか、そこだけ説明を求めました。","respondent":"中元広報広聴課長","answer":"こちらとしては「しながわネットＴＶ」という名前で検索ができるように工夫してまいりたいと考えているところです。不動麗子の件ですが、そういうものを流させていただいて、それをきっかけに検索していただくというキャンペーンをやらせていただいておりました。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"もちろん名前はいいのですが、「品川区」と入れても「しながわネットＴＶ」に飛んでいくような工夫をしてほしいと求めました。電車の広告で流していただいて１,４００回とかだと、まだまだ見てもらえるものはあるのかなと思うので、ぜひ工夫してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"}]},{"id":"topic-04","title":"第２２回品川区世論調査","agenda":"第２２回品川区世論調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"その辺のところを伺いたいのと、１５分野４０問を１つ１つ確認して、ご意見を聞くという調査方法なのかどうかを伺います。５ページの区議会への関心のところなのですけれども、本当に多くの方に行き届くような努力をしていただきたいということが要望としてあります。","respondent":"中元広報広聴課長","answer":"今年度世論調査を実施するに当たり、希望が来ましたら、ヒアリングをします。昨年の状況とか過去の状況とかを検討しながらある程度絞り込み、やはりある程度、各課として施策を考える中で調査のほうも考えているです。","id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"個別のいろいろな要求について伺うというのはなかなか難しいところがありますよね。もうひと工夫というか、もう少しあったほうがいいかなと思いましたので、今後のところでよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"私は手段があるのですから、できる仕組みを持っているわけですから、そういう調査票を出していただければありがたいなと思います。意見だけ、言わせてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"大倉委員","kind":"質問・要望","question":"今もちょっとお話があったのですが、調査対象の人数と年齢について、適正かどうか。例えば選挙が１８歳に引き下げられたとかというところもありますし、あと、その他の２件にはどんなものがあるのかなというのを説明を求めました。","respondent":"中元広報広聴課長","answer":"今までの調査が二十歳以上を対象に実施しておりまして、その辺のところをどう考えるかというのは今後の課題とさせていただきたいです。今、統計的には人口であれば１,５００サンプルぐらいである程度の年齢バランス…","id":"exchange-021"},{"speaker":"大倉委員","kind":"質問・要望","question":"人数、年齢とともに、わかりました。そこにちゃんと意見は聞けているということでいいのかの確認をさせていただきたいのと、８地域にというところで、説明を求めました。","respondent":"中元広報広聴課長","answer":"回答してきた結果ですが、４０代が２２４人というサンプルでしておりまして、やはり２０代が回答数としては若干少なくなっているところです。４０代の方の回答数が構成比として２０％を占めているというところで、全体の中で３０代の方…","id":"exchange-022"}]},{"id":"topic-05","title":"大井町駅東口ペデストリアンデッキ耐震補強工事請負契約","agenda":"大井町駅東口ペデストリアンデッキ耐震補強工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"すみません、すごく基本的な質問で恥ずかしいのですけれども、９ページのこういう感じの表を私は初めて見たというか。状況を説明していただけますか。","respondent":"立川経理課長","answer":"指名競争入札を実施したのですが、その前に制限付き一般競争入札ということで条件を変えて２回実施したのですけれども、今回。こちらから一方的に指名したということで、辞退が多いです。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701406?Template=document&Id=2064#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":27122,"voices":95}},{"id":"h28-20161129-10","meetingId":"h28-cm11","date":"2016年11月29日","dateIso":"2016-11-29","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時３３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"平成２８年第４回定例会","agenda":"平成２８年第４回定例会","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"平成２７年の、国税庁のほうで昨年の、勤労者所得、年間の平均給与が４２０万円と公表されました。２３区の公務員平均給与が６６０万と、我々の会派としては、反対をしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701951?Template=document&Id=5204#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":1296,"voices":10}},{"id":"h28-20161130-14","meetingId":"h28-cm11","date":"2016年11月30日","dateIso":"2016-11-30","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 １時１０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"公有地等、公共施設活用に関すること","agenda":"公有地等、公共施設活用に関すること","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"教えていただければ、今、お話しいただける範囲で伺えればと考えています。あわせて、その２点を伺えればと思います。","respondent":"柏原企画調整課長","answer":"５,０００平米程度にしていますのは、容積率のことを考えますと、高さをとるのはなかなか難しいという要件もあります。この方針に合うような形で進めていますけれども、そこは我々も考慮しながら、しっかり連携をとりながら進めていくということで行っているものです。","id":"exchange-001"},{"speaker":"渡部委員","kind":"質問・要望","question":"１年たちますと、学事制度のほうがある程度、一定の方針が出てくると思いますので、よろしくお願いいたします。この５,０００平米というものは、一括で、全体の中で一塊になっているところが５,０００平米と思っていていいのかどうかがわかれば説明を求めました。","respondent":"柏原企画調整課長","answer":"最初にご説明したように、東京都とも調整を図るべく、いろいろなお話はさせていただいているところではあります。我々としては、場所がどこかというのは別にいたしまして、どこかまとまった形での面積をとりにいければという形で思っています。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"徐々にではありましょうけれども、また方向性とかが出てきたら、この委員会等で報告ほしいと求めました。要望させていただいて終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問・要望","question":"まとまった土地の５,０００平米のほかに、少し区が用地を買収というようなことも考えられているのかということを確認させてほしいと求めました。その上で、この道路の拡幅が、どういうふうなまちづくりになっていくのかということをお聞かせほしいと求めました。","respondent":"柏原企画調整課長","answer":"別の土地は別の土地と分けて考えていただけるかどうかを含めて、今、そういった考え方がとれるかということで打診をさせていただいているところです。その道路の問題は重要視しておりますので、改めてお話もいただいているところですが、強く進めていきたいと思ってあります。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"その場合は、５,０００平米とはまた別に、改めて、ある程度のところを取得するという考え方になるわけですか。さっきの５,０００平米とは別に取得なのかというところだけ、再度、確認をさせてください。","respondent":"柏原企画調整課長","answer":"思いといたしましては、区は別でと考えていますけれども、これは、今の段階では、まだ国の土地ですし、東京都が全体の防災の関係で公園を大きくしたいという考え方がありますので、そことは調整しながらですが、思いとしては、別として、声を上げていきたいと思ってあります。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"１２の種類の施設が並んでおりますが、この中で５つの地区別にバランスよく配置する方針がある施設はどれになるのか、区の考えを伺います。スケジュール感をお伺いします。","respondent":"柏原企画調整課長","answer":"３カ月以内に回答ということなのですが、処分する前から、東京都が国にずっと打診をしていたという状況があります。東京都、区を含めての調整、話し合いは今後もしていかなくてはいけないという認識です。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"ここら辺を区として活用するお考えはないのか、伺います。合計２万３,０００平米余のうち、区が５,０００平米ということで、５分の１程度になるわけですけれども、それしか取得しない理由があれば伺います。","respondent":"柏原企画調整課長","answer":"５,０００平米ほどあれば、そういった行政需要に対応するものが一定程度、５,０００平米という数字をまず挙げさせてもらったです。まず、そういった面積、行政需要のところから考えた中での面積をまず確保したいというところで出させていただいたものです。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"後段に伺った水色の通路の下にちょっとある都有地があったと思うのですが、そちらについてはどうなのかというのをあわせてお伺いしたいと思います。５,０００平米にとどまらず、購入をすべきだと思いますけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"こちらにつきましては、現在、実際使える、すぐ動かせる土地ではないと我々は認識しております。区としては進めなくてはいけないというのも１つありますので、そういったところを考慮しながらのこういった判断です。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとお伺いしたいのは、１人当たりの面積を満たしていないということなのか、１人当たりの面積が一番小さいということになっているのか伺います。品川区内に１０ぐらいの広域避難場所がありますけれども、そういった満たしていないところはほかにどれぐらいあるのか、わかれば説明を求めました。","respondent":"柏原企画調整課長","answer":"１平米を満たしていないのは、避難有効面積を広げたいという意味で、東京都が取得したいと聞いてあります。こちらでは持ち合わせがないのですが、林試の森公園が一番、その面積については小さくなっているというところで聞いてあります。","id":"exchange-009"},{"speaker":"安藤委員","kind":"意見","question":"広域避難場所の指定の見直しなども含めて、広域的、総合的に考える必要があると思います。１平米というところまで改善したとしても、５,０００平米より多く残ると考えていますので、今後とも工夫をしていただければと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"学級数を増やすというけれども、まだまだ不安のある中で、ここに小山台小学校を移転するという考えはないですか。４６号線に面しているので、教育施設として、学校用地として買うというのは頭の中にはないのか尋ねました。","respondent":"柏原企画調整課長","answer":"１つ、そういったところを考えたときには、なかなか難しい判断になるとは思ってあります。なかなか厳しそうな回答は得ているのですけれども、小学校をいきなりここに持ってくるというのは、課題が幾つかあるとは思ってあります。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"こういう考え方は、これを買う東京都、品川区の頭の中にあるのでしょうか。その辺をお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"品川区の部分からちょっとというお話は、施策というところもそうですし、住んでいる方々の思いも理解はしています。配慮、そういったところを考えながら、何かうまい施策ができないかどうかというのは検討していきたいと思ってあります。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"私の聞いている話では、消防の出張所をこちらに移転する話もあるやに聞いているのですけれども、このような情報は品川区には入っているのでしょうか。その辺もお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"まだ確定ということではなくて、我々もこの土地については、これから細かい調整、交渉に入っていきたいところです。建替えに向けて土地を探しているというところはお話を聞いておりまして、一部、この国家公務員宿舎も想定したいというお話は聞いているところです。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"それと、ちょっと細かい話なのですけれども、日光の光林荘は、区外教育施設には入らないのですか。表ではどういうことになっているのか説明を求めました。","respondent":"柏原企画調整課長","answer":"一定程度、全体の清掃の業務といったところも考えながら、その再編というのは検討しなければいけないと思っています。２０年の縛りが、もうあと数年、４年、５年ですので、具体的な検討というのは入っていかなければいけないと思ってあります。","id":"exchange-014"},{"speaker":"あべ委員","kind":"確認","question":"今後、タイミングを合わせて議論すべきことだと考えていますので、清掃についての検討体制をどのようにお考えかを教えてください。確認だけです。","respondent":"柏原企画調整課長","answer":"我々といたしましては、施設のあり方というところを考えたときに、清掃の施設は全体を見ながらというところで検討をしていきたいと思ってあります。それから、保養施設の部分は、その他の区外２のところに、光林荘、しながわ荘ということでカウントをさせていただいているもので…","id":"exchange-015"},{"speaker":"あべ委員","kind":"質問・要望","question":"２つ目の小山台のほうなのですが、いろいろ要望をしてきて、随分かかったと感じております。単体の施設がぽんぽんと建つだけではなくて、エリアとして、魅力あるエリアにしていくという発想があるかどうかということを説明を求めました。","respondent":"柏原企画調整課長","answer":"１つの建物で行政需要を満たしたいということで、単体のものではなく、複数も想定しながらということで検討をできればと思ってあります。面積がどれだけとれるかというところもあるのですけれども、そういったところは一定程度、考えながら検討はさせていただきたいと思っていま…","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"どうなのでしょうか。どのような形で進んでいくのか尋ねました。","respondent":"柏原企画調整課長","answer":"全体として検討をしていきたいということで、我々が中心になりながら、全体として検討をしたいというのが思いです。東京都との今後の調整の中で、どういったスケジュール感で合わせられるのかというのも含めて、お話はしていきたいと思ってあります。","id":"exchange-017"},{"speaker":"あべ委員","kind":"意見","question":"いろいろ技術的な問題もあると思いますので、ぜひ、現場の声をよく聞きながら検討を進めてほしいと求めました。道路のほうは、できるだけ早く、広い状態でつながるように、ぜひとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"}]},{"id":"topic-02","title":"補助金・助成金のあり方に関すること","agenda":"補助金・助成金のあり方に関すること","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"一番伺いたいところは、これは何件あるかという中で、その全てについて効果の検証というのを毎年やっていらっしゃるものなのでしょうか。それは、多くの補助金でそういうことを感じることが多いものですから、どの程度の効果検証をされているかということを説明を求めました。","respondent":"秋山財政課長","answer":"委託の第三者の評価であるとか、そういうところがありますので、それぞれの事業に沿って効果の検証は行われていると考えているものです。中では１件ずつ、では、次年度もこれでいこうという形で検証をしていると考えているものです。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"もちろん企画のほうで１件１件、それがきちんと検証されているかどうかの検証というのは、そこは手綱を持っていってほしいのです。そうなのですかということをお伺いしたいと思います。","respondent":"秋山財政課長","answer":"決定をするという作業がありますので、当然、所管での議論というのがあると考えています。今、それは常によりよくしていかなければいけないだろうし、そこは考えていかなければいけないだろうという課題だとは考えております。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"もうちょっと具体的に。今、どういう部門をよりよくしていかなければいけないのか、何を考えていこうと思っているのかを説明を求めました。","respondent":"中山企画部長","answer":"典型的な指標を１つ出して、実施計画事業を担っているものであるとか、総合戦略の中でもそういう取組みをやっていこうということです。やはり助成制度の効果はしっかりとっていくというのは、区全体の中で、企画部門でも考えているという状況です。","id":"exchange-021"},{"speaker":"あべ委員","kind":"意見","question":"だから、そこをしっかり拾って、目に見える形にしていく努力が必要だと。今日はこのあたりにしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"沢田委員","kind":"質問","question":"例えば幼稚園に変えるときに、最初に出した補助金は、その目的とは変わってくることがあるではないですか。もうできているものに対して、どうやってその対応をしているのかというのを聞かせてください。","respondent":"秋山財政課長","answer":"年数的な縛りを明確に書いてあるというのは私の記憶ではなかった感じがしますけれども、すみません、正確にはお答えできないで申し訳ありません。ただし、いろいろな行政需要がありますので…","id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"そういった施設関係の補助で、実際、そういうことは今まであるのですか。補助金は高齢者の施設で出していて、すぐやめることになってしまった、そういうことはどういう対応をされているのか。","respondent":"秋山財政課長","answer":"区単独で出したもので、そういうものは承知はしておりません。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"２点、お伺いします。その点についてご説明ほしいと求めました。","respondent":"秋山財政課長","answer":"ただ、それぞれの補助の中には、国が１０分の１０出しているのもあるので、なかなか一律には言えないと思ってあります。そういう出したものがどういう形ででき上がっているのかというのがまず１点ありますし、不燃化率の向上というところの数字が出てくると考えています。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"感覚でいいのですけれども、もしわかればということでお伺いしました。お伺いしたことがわからなかった、やられているのかどうかというのがよくわからなかったので、お伺いします。","respondent":"秋山財政課長、藤田都市環境部長","answer":"１件１件、今、私が手持ちで持っているものではお答えできないと思っています。つかみでというお話ですが、それをこの中でどのぐらいかというのはなかなか難しいので、ご容赦いただければと思います。 概念的な部分になってしまうかもしれませんけれども、例えば大崎の開発については、社会資本整備総合交付金等をいただきながら事業を進めております。開発事業者を支援する形になっておりますけれども、それに答える形で評価をし…","id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"そういった補助金はどうされているのか。６月の資料の中で見ますと、残ったものは、どういうふうになっているのか説明を求めました。","respondent":"秋山財政課長","answer":"お渡しするわけですので、その事業の実績をきっちり調査しまして、それで余ったものであれば戻していただくということをしております。もちろん、その調査についても、必要な書類等を調べて、その金額についてきちっと見直して、余るようであれば戻していただきます。","id":"exchange-027"},{"speaker":"こんの委員","kind":"質問","question":"どのように検証されているのかと、ほかの委員からも質問がありましたけれども、例えば、ここに書いてある、効果が乏しいものはないか。私が申し上げた効果に乏しいものはないか、ここに挙がっているものについての検証をもう少し具体的にどうされているのか、ご説明願いたいと思います。","respondent":"秋山財政課長","answer":"それらについて、ここでは効果が乏しいという１つに抽象的な言葉で書かせていただいたのが正直なところです。この事業で対象の人数は何人を考えているというものに対してお金を出して、区として、その後の処理に入るという形でやっているものです。","id":"exchange-028"},{"speaker":"こんの委員","kind":"質問・要望","question":"どういう効果があったのか、その事業が本当に適正に効果があってしたものかというところでは、非常に難しい検証の部分だろうと思うのです。ぜひ、その点は、最後に確認をさせてほしいと求めました。","respondent":"秋山財政課長","answer":"先ほど常にということでお話をさせていただきましたけれども、部長からも答弁させていただきましたように、ＫＰＩとか数値目標、アウトカムという形で、いろいろ区の事業も含めて入ってきておりますので、それを用いて評価なり見える化なりをしていきたいと考えています。","id":"exchange-029"},{"speaker":"若林委員","kind":"質問","question":"チェックという部分で、監査委員からの補助金制度に対して、今、こんの委員がおっしゃったような見える化。議会、区民がきちんとチェックできる、見える、こういう指摘というのは過去になかったのか尋ねました。","respondent":"秋山財政課長","answer":"区の事業が決算として出たときに、決算の審査を監査委員にやっていただきますので、その中でいろいろなご指摘があると考えています。補助金について、監査から具体的にどんな指摘があったかというのは、記憶がないと考えています。","id":"exchange-030"},{"speaker":"若林委員","kind":"質問","question":"質問等の答弁でも理解をしておりますので、また区民にも、確かに見えていますと。見直すものは見直す、しっかりこういうＰＤＣＡをまた構築していただければということで、これは意見で終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"}]},{"id":"topic-03","title":"平成２８年陳情第１１号 国土交通省の首都圏空港機能強化による羽田空港増便の環境と住民の健康への影響","agenda":"平成２８年陳情第１１号 国土交通省の首都圏空港機能強化による羽田空港増便の環境と住民の健康への影響","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"ＰＭ２.５などについて、実際の数値と、あと環境基準値を教えてください。加えて、場所がどこにあるのかも教えてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"一般測定局ですが、八潮につきましては、年平均値が１５.４となっておりまして、若干、基準に達していない状況です。日平均値３５ですけれども、こちらも３６.３となっておりまして、３５より若干、基準値に達していない状況になっております。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"八潮については、ＰＭ２.５については、年についても日についても満たしていないということでしたけれども、東京都の出している資料の中で、豊町の数値も出ている、測定局も出ているのですが、それはないのか尋ねました。","respondent":"三ツ橋環境課長","answer":"東京都で測っておりますのが、品川区内では、ＰＭ２.５につきましては八潮、また、委員ご指摘の豊町についても、一般測定局についてはあります。年平均は１４.５で達成しているのですけれども、３５の基準のところが３６となっておりまして、基準値には達成していない状況です。","id":"exchange-033"},{"speaker":"のだて委員","kind":"確認","question":"航空機からの大量の微粒子が排出されていることが確認されたという報告書も出ております。区民への悪影響はないと考えていらっしゃるのか、伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"区の考え方ですけれども、航空機につきましては１５０の中の１ですので、ごくわずかであると。運輸でありますものが３分の２を占めており、航空につきましては１５０分の１というふうに、非常にわずかと環境省が申している状況です。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"その１５０分の１というのは、限定的と言ってはいますけれども、本当にそうと言えるのか。区内での値の上昇というのはあり得ないのか、伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"したがいまして、ＰＭ２.５、また大気汚染につきましても、まずは、今、現状を測定している段階です。実際に、豊町、また八潮につきましても、ＰＭ２.５は測っておりまして、実際、基準値よりは高い状況にはありますが、引き続き注視している状況です。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"国に対して、ＰＭ２.５などの発生源の実態など、健康影響などに関する正確な情報やデータを適切に提供することという要望が行われています。区としては、今、国交省から、実際的な影響が示されないもとで、明らかにしていく必要があると思いますけれども、いかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"騒音関係につきましては、実際に今までずっと国に要望しておりまして、測定を実施するということを勝ち取っています。どのように調査ができるのか、事業者の主体である国が何をするべきなのか、そのあたりを実際に国に確認はしています。","id":"exchange-036"},{"speaker":"のだて委員","kind":"確認","question":"実際に国が何をしていくか確認していくということなのですが、今、確認できているところはどういったことがあるのか、お話しほしいと求めました。値がどう変わるかということもしっかり想定していかなければならないと思うのですけれども、影響は限定的だというお話ですが、区のお考えを伺います。","respondent":"三ツ橋環境課長","answer":"今回につきましては、飛行経路の変更という部分ですので、環境影響評価条例にもあたらないという返事はいただいております。区といたしましては、やはり環境影響に配慮したものを考えていかなければいけないと思っておりまして、国に対して要望しております。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"国に対して、環境アセスメントをやるように求めているということでしょうか。そして、値が上昇するかどうかということもお聞きしましたので、お答えほしいと求めました。","respondent":"三ツ橋環境課長","answer":"法や条例としてはできないという答えはいただいておりますが、環境影響につきまして、配慮するものに準じたものができるかどうかを確認しています。１５０分の１という、ＰＭ２.５ですと、非常に難しいところだと考えています。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"法に準じたアセスメントのものをできるかどうか確認しているということですので、ぜひ、区からも強く言ってほしいと求めました。国がやらなかった場合は、区として、区民にどういった影響が出るのかというのを明らかにしていくべきだと思いますけれども、お考えを伺います。","respondent":"三ツ橋環境課長","answer":"しかしながら、例えば、何かの結果の場合に、できないという結果が出た場合、区がするかどうか。事業者は国ですので、国がやらなければいけない問題だと考えています。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"やるまで粘り強く求めていってほしいと求めましたし、アセスメントでなくても、そこも積極的に行っていくようにお願いしたいと思います。伺います。","respondent":"中村都市計画課長","answer":"２つ目の質問ですけれども、これは今、これから検討していくということになっているです。この中身がどうなるかも含めた検討を今後していくです。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"２０１５年度の航空事故の重大トラブルが３９件だと国交省から発表されておりまして、前年度、２２件の１.８倍、過去１０年で最多の年になっている。墜落の事故が発生した場合にも検討をして、防災計画に盛り込んでいってほしいと求めましたけれども、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"危機管理というのはいろいろなジャンルがありますけれども、航空機につきまして、さまざまな可能な限りの予測の中で、できる限りの対応が中身に盛り込まれていくように検討してまいりたいと思います。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"新ルートが実施されることによって、区民に多大な影響がある。この影響をしっかり明らかにしていくべきだと思いますので、ぜひ、採択していただきたいと呼びかけて、終わりにしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"お伺いしたいのは、品川区内でも、総排出量のうち飛行機の影響というのは１５０分の１なのでしょうか。そこら辺をお伺いします。","respondent":"三ツ橋環境課長","answer":"騒音につきましては、大井町が８０デシベルと国が言っておりますので、目黒駅は、それよりも音は少なくなると考えております。したがいまして、国に対して品川区の影響がどの程度になるのか、そちらは確認していきたいと考えています。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"それと、落下物についてもお伺いしたいのですが、落下物についても、この間、品川区は予見しないと言って、ちょっとどうなのかと思っています。それが人に当たった場合どうなるのか、戸建住宅に当たった場合どうなるのか、伺います。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"１５０分の１という部分は、確かに、全ての発生源ごとの汚染源の中で試算したものですので、航空機については１５０分の１です。ＰＭ２.５に色がついているわけでもなく、実際のデータとして… そういった中では、実際に落下物が何件あるとかは、予測は本当にできないところです。それを確実に実行していただくように強く申し入れを行っていく必要があり、また、それを引き続いて行っていきたいと思います。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"大気汚染のところは１５０分の１、やはり１５０分の１とは違ってくるだろうと申し上げましたので、見解をお伺いしたいと思います。これは人に当たった場合どうなるのか、戸建住宅に当たった場合どうなるかというのをお伺いします。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"引き続き、どこの駅がどの程度なのかという部分につきましては、確認はしてまいりますが、品川区全体の中で、主要駅が非常にたくさんあると思います。五反田駅ですとこのぐらいの値というものにつきましては、再度確認はしてまいります。 こういった部品、落下したものが人に当たったときの影響というのは、これは申し訳ありませんが、被害はあるだろうと思いますけれども、ただ、それがどの程度かというのは予測は私からは申し上げられません。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"落下物のリスクはもっと高まると思うのですけれども、リスクが高まるかどうか、品川区の見解をお伺いします。成田空港と羽田空港のルートではかなり違うと思うのですけれども、どれぐらいの違いがあるとお考えなのか、あわせてお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"ただ、一方では、国のまたある説明では、足下げが落下物に直接起因していないという最近のデータがあるというようなことも言っています。詳しい数字は把握しておりません。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"何が理由でしょうか、このほかにも航空会社に洋上での足下げの実施を求めるなど、そこはしっかりと認識を持ってほしいと求めました。品川区としては、どのような説明を受け、そして、どの程度、効果があると評価されているのかお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"この駐機中の点検につきましては、今度、新たに制度として取り入れようと国として考えているという説明を受けております。まだ、これから検討されるものだと認識をしております。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"１１月２２日に共産党が行いました国交省との交渉の場がありまして、そこの場で、この対策について伺いました。年間４割ですので、１４６日、伺いたいと思います。","respondent":"中村都市計画課長、三ツ橋環境課長","answer":"安全基準にのっとった航空機で飛行しているという国からの説明がありますけれども、それに加えて、一定の効果があるとは考えております。これは国もそういった説明をしておりましたが、区としても継続して、引き続き求めてまいります。 基本的には変わっておりませんけれども、ただ、２４時間の平均で重みづけをしているというＬｄｅｎにかわりました。実際に航空機が変わっていたり、沖合展開という部分で、騒音の影響は少なくなっているです。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"２点お伺いしますが、どうして最も被害が大きい自治体の１つである、この品川区ではやらないのか伺いたいと思います。どうしたら品川区内で教室型説明会が実現するのか、区のお考えを伺います。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"平成２５年４月より新基準に変わりまして、地域累計が５７、地域累計が２の部分につきましてはＬｄｅｎ６２となっております。こちらは平成２５年４月より新基準に変わっております。 フェーズ２ということで、オープンハウス型の説明会を国がやってきたところで、さまざまな形式の説明会があるのだろうと思います。かねてから教室型説明会を求めているものですので…","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"基準のところですが、新ルートが平成２６年の夏だったと思うのですけれども、その１年ちょっと前に基準が変わっているということになるのでしょうか。そこについてもお伺いします。","respondent":"三ツ橋環境課長","answer":"したがいまして、今まではＷ値というものでございましたけれども、こちらが国際基準にのっとったものになったです。実際にきちんと国際基準にのっとった評価ですので、過大評価、過小評価という観点ではございません。","id":"exchange-050"},{"speaker":"筒井委員","kind":"質問","question":"この新ルート案で、足下げの位置は大体どこになるのかということはご存じなのか尋ねました。","respondent":"中村都市計画課長","answer":"この飛行経路案、こちらはあくまで案ということで、まだ具体的な足下げの位置ですとか、そういったものは国として具体的な説明を受けておりません。というのも、まだ決定をしていないのだろうと考えております。","id":"exchange-051"},{"speaker":"筒井委員","kind":"確認","question":"大体、先ほどご答弁された主要駅の高度とか騒音というのもわかっておられるので、おそらく足下げをするという位置も、技術的には大体わかると思いますので、その点のご確認をお願いしたいのですけれども、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"私も、そこら辺の専門技術的なところはよく存じ上げません。ここからこのぐらいの間に足を下げるとか、そういったものはある程度は推測できると思いますので、そういったものを国に対して求めてまいります。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問","question":"品川区の今の大気の環境と状況というのはどのように区として捉えていらっしゃいますでしょうか。実際に２３区内で極めて高い値と言えるのか尋ねました。","respondent":"三ツ橋環境課長","answer":"しかしながら、それが品川区全体かと申し上げますと、住宅地域もありますので、一指標として大井中央陸橋を測っております。やはり大気汚染につきましては広域的なことだと考えておりますので、引き続き、そちらとあわせて申し入れていきたいと考えています。","id":"exchange-053"},{"speaker":"あべ委員","kind":"質問","question":"先ほどお伺いしたのですけれども、今、お答えをほしいと求めました。ざっくりでいいのですけれども、それぞれの排出における寄与率、構成割合というのはどのように考えていらっしゃいますか尋ねました。","respondent":"三ツ橋環境課長","answer":"引き続き、東京都に対しても、また国に対しても申し入れていく予定です。しかしながら、パーセンテージで出すことができないのですけれども、船舶の影響や、また、大きなトラックの影響等を考えております。","id":"exchange-054"},{"speaker":"あべ委員","kind":"質問","question":"東京都として、なかなか品川区だけで八潮地域の汚染問題に取り組めないと思うのですが、どのような働きかけをしているのでしょうか。どういう由来で大気汚染があるかというのはデータとして推計値が出ているわけですから、技術的に不可能ということはないと思います。","respondent":"三ツ橋環境課長","answer":"区独自で取り組むのが非常に難しい部分ですが、また、東京都が何をするべきか。どうしても車の影響もありますので、そちらにつきましても、東京都に対して広域的な部分で申し入れてまいります。","id":"exchange-055"},{"speaker":"あべ委員","kind":"質問・要望","question":"環境にかかわる健康の問題については、どのように捉えていらっしゃるのでしょうか。これだけ恒常的に大気汚染がということになると、例えば呼吸器系の疾患などが多いという現状もあるのか尋ねました。","respondent":"三ツ橋環境課長","answer":"こちらは健康課主体で、そちらで取り組んでいる公害補償制度などがありますので、そちらで取り組んでいる状況です。実際にＰＭ２.５の測定局を設置するにあたっても、八潮に測定局を設置することができたのは、ＰＭ２.５の設置もしている状況にありますので。","id":"exchange-056"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこに変化があらわれるかどうかというのは、区でも把握できるようにしておいていただきたいと思うのですが、いかがでしょうか。ご答弁できますか。","respondent":"三ツ橋環境課長","answer":"実際に、３時から７時の間に飛行機が通るということで、国がどの程度の健康被害を考えているのか。そのあたりにつきましても、国に対して確認してまいります。","id":"exchange-057"},{"speaker":"あべ委員","kind":"質問・要望","question":"そういったことが、それぞれわかるわけですので、飛ぶ前と飛ぶ後と比較ができるようにしておくことが大切だと考えています。さまざまな努力、対策というのは、ぜひとってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"新妻委員","kind":"質問・要望","question":"ここは改善を求めていく必要があると思います。データ、正しい数値に対してどう影響があるのかということも含めて、また東京都なり国なりに求めてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"実際に、八潮の状況につきましては、やはり基準値を達成していない状況もあります。広域的にわたって、実際にしなければならないことがたくさんあると思いますので、きちんと申し入れてまいります。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"新ルートによってどういった影響が出るのかということを明らかにしてほしいということですので、区としても、まだ説明は不十分だと言っているものもありますし、しっかり明らかにしていくことが必要だと思いますので、結論を出すということで、採択を求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"あべ委員","kind":"質問・要望","question":"先ほども申しましたが、この地域的な環境の問題のデータですとか要望というのは、それはもう粛々と進めてほしいと求めました。それを添えまして、この陳情については継続でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"同じように、現在、この新ルートによって影響がどうなるかということですので、結論を出すということで、採択を求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858443?Template=document&Id=6020#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":54623,"voices":156}},{"id":"h28-20161201-18","meetingId":"h28-cm12","date":"2016年12月1日","dateIso":"2016-12-01","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"バリアフリー整備に関連をして、何回もここでも言っていますけれども、立会川駅からの大井ふ頭中央海浜公園までの間のバリアフリーですね。それから首都高速道路の下のところを通っていくわけですから、そこのところのコースの安全対策等も検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ずっと議会で要望がされてきておりますし、地域の方の請願という形でも出していただいておるところでありますけれども、特に新馬場についてですね。お願いをしてどういう反応なのかというところをお伺いしたいというところと、そこについてのお考えを伺いたいと思います。","respondent":"中村都市計画課長、小川オリンピック・パラリンピック準備課長","answer":"ただこれも鉄道事業者からは、努力はしたいというところで検討をするというような回答までで、まだ回答は得ているところではございません。引き続き具体的な内容につきましては、また東京都とも詰めていく必要がありますが… ４７番の「競技・文化プログラム等をバリアフリーで鑑賞できる環境整備について…」ですが、今、まさに進めているところです。都立施設等につきましても、区といたしましては引き続き要望しています。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私が以前伺ったときはもう既に京急の新馬場などは７回ぐらい折衝しているというお話もありましたけれども、東京都、国の力も得ながら。効率的な運用をしていただきたいというところ、これもしっかり確認をしていきたいなと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"いながわ委員","kind":"質問・要望","question":"私からちょっと１点お伺いをさせていただきたいのが、バリアフリーと一言で言っても、例えば世界的な基準があったり、日本の基準があったり、あとはオリンピック・パラリンピックの大会組織委員会の中での基準があるのかどうなのか、まずその辺をお聞かせほしいと求めました。","respondent":"多並道路課長","answer":"そちらのほうで検討しておりまして、１８０項目ぐらいあるらしいのですけれども、現在それは発表されているところです。具体的なそれ以外の項目については、まさに今それを大会組織委員会等で検討していると、そのように聞いているところです。","id":"exchange-004"},{"speaker":"いながわ委員","kind":"提案","question":"オリンピック・パラリンピックの後のバリアフリーにも活かせますよという提案をして、そういった絡みを簡単にお聞かせいただきたいということです。提案としてはそういうところに、区のほうで可能なのかどうなのかというところは、提案と可能かどうかというのを教えてほしいと求めました。","respondent":"多並道路課長、中村都市計画課長、小川オリンピック・パラリンピック準備課長","answer":"誰でもご利用しやすい環境を整える、そういうお使いされやすいような整備を進めるべきというところが、それを今協議しながら考えているところです。… 非常に難しい、現在の考え方では既存の駅を改修してさらなるバリアフリーに対応するということで、基本的にはその考え方で進められております。… ボランティアがいろいろ補助をしていたかと思うのですが、東京２０２０のときにも、当然そういうことになろうかと思います。…","id":"exchange-005"},{"speaker":"いながわ委員","kind":"提案","question":"しっかりと国や東京都に、何というのでしょう、提案をしてそれを実現していくような形でお願いをしたいと思います。例えば東急口というのですか、何というのでしょう、なかなか難しいのではないかなと思いますとの意見を述べました。","respondent":"中村都市計画課長","answer":"今、今度階段が狭くなってしまって、非常にどうしたらいいかというところはなかなか難しいところというふうには聞いております。今後また検討していきたいというような回答を得ておりますが、ここは区は引き続き、申し入れをしていきたいと考えております。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"確認","question":"ここのバリアフリー、当然品川区の直接の管理ではないのですが、これも当然品川区内のことなので確認をお願いしたいと思います。お願いいたします。","respondent":"多並道路課長","answer":"実は先ほどちょっとお話しさせていただきましたアクセシブルルートの観点で、潮風公園の周辺についても、今ちょうど検討しているところです。それをやりながら会場周辺の、そういうものを設定しながらバリアフリーにしていくということで、現在情報は仕入れているところです。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そこで品川区の意見はどれだけ取り込むことができるのでしょうか。電車を通すとか、ぜひ品川区の意見を相当盛り込んでいただくようにお願いしたいのですが、それは可能性ありますか尋ねました。","respondent":"多並道路課長","answer":"その会議体としては、今回ホッケー場の周辺も関係ありますので、そういう関係で我々品川区も入る予定だと思います。そこの整備計画に盛り込まれるような形で、意見は言うことはあると思いますが、そういう場を通じて考えていきたいと思っているところです。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問","question":"ここが全く計画がないというか、京急のほうは全く、今も計画がない状況なのでしょうかということをお聞きしたいと思います。ですので、全ての障害の分野、そういったところを聞きながら取り入れていくというふうに進めていただけるのかどうかということを伺いたいと思います。","respondent":"中村都市計画課長、中山障害者福祉課長、多並道路課長","answer":"今、鉄道事業者からは、ホームドアを設置する計画等はまだ聞いておりません。今、この駅の京急各駅の耐震化を進めるのがまず優先事業として進めているとこ… 多様な障害のある方についてのバリアフリーというところですけれども、今までもそうした声を聞きながら事業を行っております。… 今考えているのは、今検討しながら、あとは観光地周辺ですね。そういうところをよく、しっかり見ながら、可能な整備ということで考えていきたいというのが…","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当にもう２０２０年、ぜひ強力に、こちらからも要請をしていただきたいなと思います。観戦できるというところでは、引き続き声を聞いていって、そして一緒に進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"要するに一般の方の支援ということを求めていたのかなというふうに私は感じていたのですが、こういう、これから区のほうとして。ですから通常での支援という面で、その辺をちょっとお答えいただければと思うのですが。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういったことで区民の方みんなで盛り上げていくという機運を醸成するために、ボランティアというような位置づけで養成している講座です。そういったことを区も先駆的に実施をする中で、今後も区としては考えてまいりたいと思っています。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。その辺を区として、またこれから積極的に詰めていただきたいなと思いますので、その辺ではどうか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"例えば区のほうでも、スポーツ推進委員を対象にユニバーサルマナー研修を実施したりですとか、実際に車いすに乗られている方を講師にお迎えして。少しずつ区としても進めているところですので、オリンピック・パラリンピックを契機にますますやっていきたいと考えています。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。これからもぜひお願いしたいのと同時に、これからもその辺力強くやっていただきたいなということを要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"こういう下からの積み上げでこうしてほしいとか、ああしてほしいとか、なかなか大変になってしまうのではないかなと思うわけです。１兆円を切ってやってくれみたいな、その辺の考え方、見方をどういうふうにしたらいいのかというのをちょっと教えていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"当然といえば当然ですけれども、わかりました。構図というか、そういうものをちょっと知りたいなと思ったので、そこも教えてほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"それはそれぞれの、東京都のほうでお考えになって、区といたしましてはできるだけ補助金を活用してという考え方があります。それぞれ関係のところ、例えば特別区の担当課長会などもありますので、そういったところで情報共有はできるという状況です。","id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"３兆円だのというふうな数字がひとり歩きして、ようやくこの間２兆円以内にとどめるというふうな、小池知事は２兆１,０００億円と言ったのかな。その辺についての考え方、そういう場面も含めてしっかり必要な発言はしていくべきだなと思っているので、ちょっとその辺を確認したいなと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"全体の経費に関しましては、先ほども申し上げましたが、国、東京都、大会組織委員会がそれぞれの責任のもとにおいてきちんと管理をしていくべき問題であると考えております。","id":"exchange-016"},{"speaker":"吉田委員","kind":"提案","question":"何というのかしら、そういうのと、この障害者のバリアフリーのことと結びつけて考えていくことはできないのかどうかという質問が１点です。こういうものをこの委員会の中で１回体験してみて、それで議会全体とか、これはちょっと提案させてほしいと求めました。","respondent":"中村都市計画課長","answer":"こちらのほうは委員ご指摘のとおり、区といたしましてこの設置の計画を事業者に示せればすごくいいと考えています。実はホーム柵を設置するに当たりましても、必要性の高いところから設置をしていただくように、そういったお願いをしています。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"補助金というのも、そこを区のほうがもうちょっと主体的に、こういう順番でつけていきたいのだと。恐らく鉄道事業者、そこをやはり補助金という形で促す計画というのですか、そういうものをぜひ持っていっていただきたいなというふうに要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問","question":"地中化についてお伺いしたいと思うのですけれども、当然いろいろ調整しながら工事をやっていると思うのですが、今の現況の工事がどこまで進んでいるのかということを説明を求めました。","respondent":"多並道路課長","answer":"今年度末にそれは終わる予定です。来年度予定しているのが引き込み連携管といいまして、東京電力のほうの埋設管工事のほうに、今度は委託工事のところで入ってくる予定です。","id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"質問","question":"すみません、橋桁の補修工事、塗装工事ということで大変失礼しました。そうすると、橋自体をまた手直しするとかについては、これから整備事業があるということでよろしいのか尋ねました。","respondent":"多並道路課長","answer":"橋自体の、橋があるところ自体は今後手を加える予定はございません。今の予定ですと詳細設計に入っていく予定ですので、ちょうどそこを今調整しながら来年度へつなげていきたいという段階が、今の現時点です。","id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"何というのですか、いわゆる景観のことについて、区としてこれからどのように要望していくのかお知らせください。","respondent":"多並道路課長","answer":"やはりそれが一緒に連携するべきだろうということで、実は今一緒にどういうデザインにするかということで協議しているところです。そういうのを今、ちょうどいろいろどうやるかというのを話しながら、来年度につなげていきたいというのが現在のところです。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"お伺いしたいのは、バリアフリー整備（会場へのアクセシビリティ）という形で括弧書きをしておりますが、改めてお伺いしますが、今のオリンピックの品川区内の、会場問題はどうなっているのか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今、東京２０２０大会の品川区内で予定されている会場は、潮風公園でビーチバレーボール、大井ふ頭中央海浜公園でホッケーの２競技が会場として予定されているです。","id":"exchange-022"},{"speaker":"藤原委員","kind":"確認","question":"続けてですけれども、今年度中にその整備をする会議が立ち上がるという話をいただきました。確認なのですけれども、その会議に先ほどの答弁では品川区から理事者が入るように思えたのですけれども、それでよろしいのか尋ねました。","respondent":"多並道路課長","answer":"国のほうが平成２８年５月３０日付で、それと一体的に進めながら、このような形で公表しているところです。その会議体については、今聞いているところによると、区の部長級が委員として入るということで聞いているところです。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"要望が出ていると思うのですけれども、そういう形で国および東京都にリクエストを上げていく一覧表といいますか、そういう形で所管としては計画を立てているのか尋ねました。","respondent":"多並道路課長","answer":"それを具体的にどう進めるかというのは、どちらかというと、大きなところについてはそこに申し入れていくべきかなと思っています。それ以外の細かい整備内容等については来年度以降の実施設計で決めていきますので、東京モノレールだったり、そういう部署ともう少し密接に。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"来年が２０１７年ですから、もうあと３年ですから、そこでどうしても確認だけはしておかないとと思うのは。そのハードの面のレガシーというのも、私は大切だと思っているのですけれども、その辺についてはいかがか尋ねました。","respondent":"多並道路課長","answer":"連携をしながら整備をしていきたいということが大きな目的でもありますので、区としても一体的に、効果的に進めていきたいと考えております。そこら辺がやはり一番進めていくところでもありますので、そういうハードやソフトを連携しながら、一体的に進めていきたいというもので…","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"要望項目の４６、４８とか、文化観光課でやられている観光事業に関して協議会をつくりましたよね。リクエストをしていっていただきたいと思うのですが、そういう意味で担当の課長、どう思われますか。","respondent":"鈴木文化観光課長","answer":"その中でさまざまな事業実施に向けた協力や、ＰＲの協力をいただいているという意味では、非常に良好な関係で連携をしております。しっかりと意見交換なり、情報共有をして連携していきたいと、またそれが可能だというふうに考えております。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問・要望","question":"こういう委員会ですので要望にしますが、別の機会でまた訴えたいと思いますけれども、そういう機会をぜひつくっていただきたいと思っています。今直近でもそういう確認もありましたが、この２０２０年のオリンピック・パラリンピックに向けての会場周辺等を含めて、確認のため説明を求めました。","respondent":"多並道路課長","answer":"今ありまして、よりいろいろな方がお使いいただけるような整備を進めていきたいという考えもありますので、現在そういう考え方のもとにやっていると。今ちょうどオリンピックに関してはやっているところなので、それに合わせて…","id":"exchange-027"},{"speaker":"つる委員","kind":"確認","question":"さまざまな機会の中で改善をしてほしいというところの意味での、区とのさまざまな連携というのは、これまでもずっとあったと思うのです。そういう中での改善すべき点というのは、そういう部分での連携ということはどうなのでしょうか、このあたりを説明を求めました。","respondent":"多並道路課長","answer":"平成５年からずっと進めていますが、品川区としてはそういう１つの考えとしては、オリジナルでやっているところもあります。このように今後も、特に今度の重点整備をやるときには一緒に連携しながら整備を進めていきたいというのが考え方です。","id":"exchange-028"},{"speaker":"つる委員","kind":"確認","question":"ということにならないことが大事かなと思いますので、そうしたところも細かく確認を連携しながら、お願いしたいと思います。世界の方々が来られるわけですから、ホームページも１２月にリニューアルをされるわけですから、このあたりの考え方について説明を求めました。","respondent":"中山障害者福祉課長","answer":"今後の考え方というところになろうかと思うのですが、今日のニュースでも新しいアプリができたとかいう情報もあります。ですから、どういった情報が一番障害のある方が安心して、オリンピック・パラリンピックに向けての課題解決に向けていければと考えているところです。","id":"exchange-029"},{"speaker":"つる委員","kind":"質問・要望","question":"これはこれからだと思うのですけれども、それを開発されているし、ほかの団体もそういうアプリを既に作られているところもあるのですよね。そういった視点で積極的にそういう情報提供をやっていただきたい、やっていただきたいと、最後要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"松永委員","kind":"質問・要望","question":"私からは大井競馬場前駅のバリアフリー化について質問と、要望も含めてしたいと思います。耐震のほうも危ないのではないかという危険性があると思うのですが、そういった話も出ているのか伺いたいと思います。","respondent":"多並道路課長","answer":"例外的な場合ということで、国の基準としては１.２ｍ以上ということで、それが今の大きなところの基準となっています。これについても、より安全性が高まるような改善ができないかということで、今言っているところです。","id":"exchange-031"},{"speaker":"松永委員","kind":"質問・要望","question":"最後に要望ですけれども、もしできるのであれば、その駅から階段のほうではなく、直接橋につながる出入り口を設けていただきたいなと思うのです。例えばそこでも、そのまま会場のほうに向かえるのではないかと思いますので、要望としてします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１点確認をしたいのですけれども、ちょっと確認なのですが、議会側からの要望がここで取り上げられています。４年後以降そういう話になってしまうと、１回ちょっと改めてそこの確認だけを、今後私たちも積極的に要望していってよろしいのかどうなのか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ちょっとそれを確認をしたかったので。何らかの形で、この応募スケジュールを見ると、品川区独自のボランティアに関してはどう考えているのかというのをちょっとお知らせいただきたいです。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"８万人や１万人は全国からすぐに集めることができるという自信を持っておりますので、今、そういったことに入る可能性は十分あろうかとは思います。都市ボランティアの、そういった状況等も踏まえつつ、区も同時並行で検討してまいりたいと思っているところです。","id":"exchange-034"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１点、これ普通の日常的な部分では非常にどんどん進めるべきだと思うのですけれども、皆様の考えの中では誰をターゲットにしているのか。多分外国人が多く来るのではないかなと思って、その辺をまず行政としてどういう視点で考えられているかというのをお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"これは当然その外国の方々も見据えた形での対応といいますか、考え方を持たなければいけないと、これは当然だと思います。これは考え方として検討しなければいけないというのはありますけれども、これは当然区として、主なところであろうかと思います。","id":"exchange-035"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そういったサイトというのですか、もちろん日本人がずっとここに住んでいるわけですから、日常的な生活もあるわけですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私も１回夜遅くにタクシーであそこの駅に行ったことがあるのですが、ただやはり、安全性を考えたときにそれは本当にいいのかなと。その辺をどのように判断していいのか、ちょっと考え方をお聞きしたいと思うのですけれども。","respondent":"多並道路課長","answer":"ただ、どう対応しなければいけないかというのは、ちょっと考えなければいけないところです。は１日ほとんどとまらないバス停が、それも含めて、中で検討するべき課題として捉えていきたいと思っているものです。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"意見","question":"本当に難しいなと思って。それと同時に障害者の方がどの程度あそこを使う方がいるかどうかも、何かいい方法をこれからも検討して、その辺との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"伊藤委員","kind":"確認","question":"そういうのを掲げていくことを伺ったので、そのことはされるのでしょうけれども確認をお願いするのと、そのことの確認で。だから、そのことはステップとして考えていくべきだと思うのですが、いかがか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長、鈴木文化観光課長","answer":"今のところ組織委員会から具体的な考え方などが示されていないのですけれども、恐らく大会の直前になるであろうという回答を得ております。いろいろな各所管で対応しているところではありますけれども、大変サイン類がなくて… 新しいツールを使った対応ということにつきましては、観光のほうでも今いろいろなツールの、新しいものとかアプリを研究しております。その情報をもとに、また言語の表示等もアレンジをすることで十分対応できると思いますので…","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは都市開発課のほうにも１回お願いをしたことがあるのですが、現状教えていただきたいのですけれども、このような考察がありました。海外の方もかなりいらっしゃるのではないかなという中で、今どのように進めているのか、そこについて確認をさせてください。","respondent":"鈴木文化観光課長","answer":"それから複数の建物の中を通過するということもありまして、わかりにくい部分があるのはご指摘のとおりだと思います。それから事業の実施者、それぞれで連携をして、お互いの役割を確認してしっかり整備すべきものというふうに考えております。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今そういうふうにしていただいているかと思うのですけれども、やはりスピード感は大事だと思うのですね。それともできるだけ早く、アズ・スーン・アズ・ポッシブルでやっていただけるのか、ここについてを最後確認させてほしいと求めました。","respondent":"鈴木文化観光課長","answer":"ご指摘のとおり、オリンピック・パラリンピックも大きな契機になります。しかしそれだけが整備の効果が活かせるものではありませんので、その辺の調整をスムーズにすることも含めて取り組みたいというふうに考えております。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、ぜひ検討もしていただきたいし、さまざまなツールということで考えていただきたいと思っています。４年あるわけなので、ちょっと伺って、ぜひこのシャトルバスも含めて検討していただきたいと思っています。","respondent":"中村都市計画課長、小川オリンピック・パラリンピック準備課長","answer":"そしてそれでも足りない場合に、必要に応じてシャトルバスも検討するというような、そういった優先順位をつけて検討を東京都ではしているです。そういった渋滞を避けるような… ３１ページで下の写真の３段目の「公園で案内する都市ボランティア」、「駅で案内する都市ボランティア」とありますが、紺の制服を着ておられました。東京大会が具体的にどうなるかは、まだ制服の色とかはわかりませんけれども…","id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"品川区がするべきなのか、東京都がするのか、そういう段階でもぜひちょっと検討もしていただきたいということを要望としてお伝えしたいと思います。それから、シャトルバスについては東京都の視野に入っているということなので、ぜひ実現もしていけるように、要望を強めていきたいなと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"いながわ委員","kind":"質問・要望","question":"何点かお伺いしたいんですけれども、何種目開催されたのかということを１点お伺いします。都内のみならず全国に発信できる体制をとってほしいと求めましたが、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"１０月２９日のユニバーサルスポーツ大会ですけれども、やった種目を並べします。","id":"exchange-044"},{"speaker":"いながわ委員","kind":"質問・要望","question":"すべての障害をお持ちの方が一緒に参加できる、一緒にプレーできるステージを提供するのが行政としての今後の一つの責務でもあるのかなと思います。今、幅広い障害をお持ちの方が一緒に楽しめるスポーツを実現していただきたいと思うということで質問しました。","respondent":"池田スポーツ推進課長","answer":"第２・第４土曜日に体育館でそれぞれ障害者スポーツ教室を行っているところですけれども、そういったスポーツ教室ができないかというようなことを考えするようにいたしますので、よろしくお願いいたします。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問","question":"私から伺いたいのは、９番のブラインドサッカーは、ブラインドサッカーというのはこういうものですよというような場だったと思います。目の見えない方にサッカーってこのように楽しいものだよということを教える教室があるのかどうかと、その辺について伺いたいと思います。","respondent":"池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長","answer":"１０番、１１番については啓発のものということになってございまして、オリンピック・パラリンピック準備課で行っているのが出前体験講座。２のその他ところで書いてありますように、もしくは地域の方と… サッカーの楽しさですとか、サッカーを通じていろいろな生きがいの提供とかいうような事業は実際にやってあります。そういった情報は区としてもキャッチしておりまして、今後場所の提供ですとかいろいろな面で…","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問・要望","question":"新しいスポーツに触れるような機会を、それは健常者も障害者も関係なく、こういう機会というものを検討していってほしいと求めました。これは要望でとどめします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは今は、今後について、そういったグラウンド・ゴルフのこういった会をもっと品川区として開催していくのかどうかをお聞きしたいのが１点です。いろいろ啓発活動をやっていると思うのですけれども、今現在の町会・自治会に対してのブラインドサッカーの取り組みをお聞きしたいと思います。","respondent":"池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長","answer":"こちらのグラウンド・ゴルフのほうですけれども、狭いところで人数的には６０人ぐらいが限度かなと考えるところです。グラウンド・ゴルフの大会につきましては、年々ますます回数も増え、そして参加者も増えているような状況です。 年間１０回分の予算をつけてありますけれども、例えば第二延山小学校ＰＴＡの方ですとか、そういったことでご利用はいただいているところです。１０人以上の人数が参加して、またなおかつ場所があれば…","id":"exchange-048","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そういったことから、ますますそういった啓発活動を町会・自治会を含めて行っていただきたいと、繰り返しの話になりますけれども、これは要望です。東京大会が終わった後もぜひそういった遺産を残して、ブラインドサッカーを引き続きやっていただきたいと思っています。","respondent":"池田スポーツ推進課長","answer":"どなたでも来てくださいというようなことで、主催者のほうでもやっておりますので、ぜひ皆さんに来ていただければと思います。地域のスポーツクラブでグラウンド・ゴルフというのはかなり盛んになってまいりまして、そういったことで、今後も変わらずやっていくような予定です。","id":"exchange-049","title":"町会・自治会支援"},{"speaker":"藤原委員","kind":"質問","question":"改めてお伺いしますが、そもそも障害者スポーツを行政が推進していく目的を説明を求めました。","respondent":"池田スポーツ推進課長","answer":"そしてやさしい心を育て、そして地域の方との交流等を行いまして、コミュニケーションを深めるということでの生きがいづくり等の目的もあります。そういったことだけではなく、行政としましても障害者の方のスポーツということで…","id":"exchange-050"},{"speaker":"藤原委員","kind":"提案","question":"まずスポーツ推進課長から伺いたいのと同時に、具体的な課題はどうあるのか、思っていることを伺いたいと思います。障害者スポーツに対してどういう課題があり、目標があるか、今の時点でどう思っているかを教えていただけますかとの意見を述べました。","respondent":"池田スポーツ推進課長、中山障害者福祉課長、小川オリンピック・パラリンピック準備課長","answer":"そういった方がぜひ週１回、実は自分は若いころから、障害を持っていてスポーツをとめられていた。だけど… そういうチームでやるようなものは、障害当事者の方たちだけでグループがつくれるぐらいになると本当は一番いいのかなと思っているところです。… ２０２０年のパラリンピックの成功をまずは目指したいとは思っているのですけれども、障害者スポーツの理解にいそしんでいきたいとは思います。ただ…","id":"exchange-051"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、障害者福祉課長からお話をいただいたのですけれども、やはり障害者の方が一歩踏み出すということが大事だと思います。行政として一歩踏み出す後押しをしていただきたいと心から思っているのですけれども、最後にそこだけ、もう一回答弁いただけますか。","respondent":"中山障害者福祉課長","answer":"そうしたスポーツといいますか、シッティングバレーですとかボッチャですとかも始めております。ですので、体を動かす楽しみ、外に出ることの気持ちよさといったものを障害のある方に伝えていきたいと考えております。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"昭和５７年、相当前からやっていたということを改めてこの資料で確認したのですけれども、私は恥ずかしいのですけれども初めて見に行きました。それは例えばどのようなスポーツが考えられるのかというところを、あれこれたくさんあると思うのですけれども、教えてほしいと求めました。","respondent":"池田スポーツ推進課長","answer":"実際には８ホールありますので、長いホールが約３０ｍで、大きさというのは特段変えることができるというものです。ボッチャについても気軽にできるスポーツでございまして、障害をお持ちの方もできるような用具もありますので、今が旬とすればボッチャかなです。","id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"ガイドの方なりお手伝いの方がいなくても、ぜひそういう方向で検討をしていただきたいということをこの場でお願いをしておきたいと。答弁はいいので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"提案","question":"１点だけ伺います。とっつきやすくする、ハードルを下げる何かそういう取り組みをしていただきたいと思うのですが、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"障害者のスポーツについてですけれども、毎年春から品川区スポーツ協会のホームページにはご案内を載せさせていただいているところです。これがリンクで飛ぶのかどうか、もしくは新たにつくるかということで、いろいろ研究させていただきたいと思います。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問・要望","question":"各媒体で、自分がどのようなスポーツをやりたいのかもよくわからない障害者の方もいらっしゃって、ぱっと見たときにやはりそれがわからないわけです。ですから、ぜひともそういう取り組みをしてほしいと求めましたが、もう一回ご答弁をお願いいたします。","respondent":"池田スポーツ推進課長","answer":"委員からご意見のございましたこちらの問い合わせにつきましては、まずリンクができるかについては研究しますけれども、もう一つの情報の発信ということについて、もっと充実できるように、これは検討をするようにします。","id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"城南５区のほうで設置を東京都に求めているということだったのですけれども、東京都の対応はどのようになっているのかというのを伺いたいです。もしやられていなければ、今後どう考えているのかというのを伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"アンケートにつきましては、回答率がおよそ４０％ぐらいあったということなのですけれども、そういったことで調査は１回ございました。その中でもいろいろなアンケートを実施しているところでございまして、障害者スポーツについて進めていきたいということを考えているところで…","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"一緒にスポーツを楽しめるという場としては本当にいいところだなと思いますので、引き続きぜひ強力に求めていただきたいと思うのです。私たちもそれに沿って、障害を持たれた皆さんと一緒に進めていくということができるのではないかと思うのですけれども、その辺いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"１０種類ですけれども、自分が楽しめる、自分に向いているスポーツは何かなというところでまず体験していただく。それからスポーツサークルのほうに入っていただくというようなこともできるかなということでやらせていただいているところです。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういう中でも、日々の生活の支援充実なくしてスポーツはできないんだということなども訴えられているのです。そういったところを進めていかないと、そういった生活全体から見て、障害者スポーツというところをどのように考えられているか伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"障害のある方がスポーツだけではなく、自分のやりたい活動を実現していくために、やはり移動の手段というのは必要かと考えています。に移動支援ですとか、その方の活動に合わせて、そちらのほうは障害者福祉課で対応させていただいているところです。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"最後にしますけれども、やはりそういったところがまだまだ不十分だというのが障害を持たれた皆さんの実感ですので、そういったところをさらに私たちも一緒に求めていきたいと思いますので、ぜひ今後もご検討をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その中でも１競技とか２競技に絞ってでも、今、そういう競技を誘致していくという方法も一つあるのではないか思うのです。中学校とのつながりもできることによって、これからの障害者スポーツにさらに結びつきができると思うのですが、その辺のお考えはいかがか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"事前キャンプにつきましては、オリンピックに限らずパラリンピックの面も視野に入れて、今、さまざま動いているところです。キャンプを誘致することによる効用は十分こちらも認識していますので、積極的にさまざま可能性のあるところで動いているところです。","id":"exchange-061","title":"町会・自治会支援"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ぜひお願いしたいです。この前会派の中の勉強会でもそんなイメージを持っているので、ぜひその辺をよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"南委員","kind":"質問","question":"一つの案ですけれども、一緒に共同で建設しようじゃないかということで働きかけをしていっていいのではないかと思っているのです。そういうところについてのご認識はどうなのかというのをまず伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"東京都の障害者スポーツ振興計画でも、今２カ所あるものについて充実しようというようなことが書かれてあります。委員からご指摘のありました城南５区で考えてはどうかというようなこともありますけれども、もう少し様子を見ていきたいなと考えています。","id":"exchange-063"},{"speaker":"南委員","kind":"質問","question":"ちょっとその辺があまりにもアバウトなので、わかりましたというふうには終われないので、そのあたりをちょっと伺います。","respondent":"池田スポーツ推進課長","answer":"区のほうも東京都の動きがどこまで動くかというところを見定めないと、城南５区としてどうなのかということができないかと考えていますので、そこのところはもう少し見定めるということで、よろしくお願いいたします。","id":"exchange-064"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点でやはりいい機会だと思うので、やはりそういう方向をしっかり確認して取り組んでいくということが大事だと思うのです。その姿勢のところでの回答を聞いて、終わりにしたいと思います。","respondent":"池田スポーツ推進課長","answer":"委員のご意見はご意見として承りますけれども、あくまでも東京都の動きがないと、私どものほうでも考えるところが難しいと思いますので、しばらく東京都の動きを見させていただいて、その上で考えていきたいと思います。","id":"exchange-065"},{"speaker":"松永委員","kind":"質問","question":"その練習を見ながら、これはもしオープンであれば見る絶好のチャンスだと思うのですが、どのような場になっているのか伺いたいと思います。その選手たちがその会場まで行くにあたってのルートのところで、何かもうちょっとこうしてほしいなという意見がもし出ていたら、説明を求めました。","respondent":"池田スポーツ推進課長","answer":"もう一つ、荏原Ｂ地域のスポーツクラブの方がこちらのお手伝いをすることも時々やられているということは、話で聞いてあります。２つ目の角を曲がればすぐ着くということで、逆に角は２カ所曲がりますけれども、かなり好評な立地条件ということになってあります。","id":"exchange-066"},{"speaker":"松永委員","kind":"質問","question":"そうすると、じゃあ、これはオープン、練習風景を外から見ることはできるということなのですね。そうなると、私は今日初めて知ったのですけれども、地域の周りの人たちというのはもうご存知なのかなということで、お伺いしたいと思います。","respondent":"池田スポーツ推進課長","answer":"練習をしているということで生徒たちにも周知していますし、周りの方にも練習をやるということで説明はされておりますので、周知ということではかなりしていると思います。","id":"exchange-067"},{"speaker":"いながわ委員","kind":"質問・要望","question":"費用もかかることなので、それはしっかりと判断をしてほしいと求めましたので、その辺ちょっとどうお考えか。本当に希望の光だと思いますので、その辺をどうお考えか、どのぐらいのやる気があるのかというところを含めてちょっと教えてほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"リオが終わったら考えるという回答を得まして、その後、委員ご指摘のとおりさまざまなルートを使って積極的にまさに水面下で動いているところです。詳細なことはまだ言えない状況ではありますが、区といたしましては、かなり積極的に…","id":"exchange-068"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひこの報告書、手前みそになってしまうと思うのですけれども大変よくできていて、非常に見甲斐があって、その一つ一つがやはり細かいミクロの部分で見ていくと本当に参考になるものなので、しっかりと活かす方向に持っていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"つる委員","kind":"確認","question":"それを支える側の視点で、そういう人材を育成していくという観点も、品川区としてできることもあるのではないかなと思います。そういう方にフォーカスをした何か講演とか機会は、この間、まず確認したいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"オリンピック・パラリンピックに取り組んだのが３年前からですけれども、その３年前から、パラリンピックに焦点を当てた啓発の講演会をしています。区長のほうに表敬訪問されたというようなことで、さまざまな切り口でパラリンピックに焦点を当てた事業等々を展開しています。","id":"exchange-070"},{"speaker":"つる委員","kind":"質問・要望","question":"なので、１区市町村あたり限度３００万円とかという話もありましたけれども、そういう方々の講演事業とかいうのも活用できるのかなと思っています。平成３０年、そういう機会をぜひつくっていただきたいと思うのですが、何か考えがあればぜひ説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういった中で、品川区は今のところすべて限度額ぎりぎりいっぱいまで品川区の事業で使う見込みとなっています。そういった中でも平成２９年以降、委員ご指摘のあったようなこともヒントにさせていただきながら、いろいろ展開をして考えてまいりたいと思います。","id":"exchange-071"},{"speaker":"つる委員","kind":"意見","question":"どうしてもそういう推進とかとなると、冒頭申し上げたように、実はその方を支えている方がたくさんいるのだと。そのところでのオリンピック・パラリンピックそのものの気運を盛り上げていく大事な視点かなと私は思いますので、ぜひとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"南委員","kind":"質問","question":"そういう扱いでいいと思うのですけれども、今、委員長がおっしゃった分野が広いので分野別にという、そこの分野別というのは具体的に項目で言うと何か尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問","question":"大分用意してきたのですけれども、今日はもうやらないということで、先ほどオリンピック・パラリンピック準備課長の説明の中で、東京２０２０参画プログラムがイコール文化プログラムではないということにご注意くださいとあったのですけれども、そこの違いについて説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"こちらの１番の「オリンピック憲章」を見ていただきたいのですけれども、オリンピック憲章の規則３９、文化イベントのプログラムを催すものとする。今回の組織委員会がさきに始めました東京２０２０参画プログラムというのは…","id":"exchange-074"},{"speaker":"あくつ委員","kind":"意見","question":"わかりました。次回、そちらのほうを見ながら、また品川区でどのようなことができるのか検討していきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"いながわ委員","kind":"質問","question":"もちろん今日１２月１日、１０月１日から認証事業が開始されているというのは、逆に品川区は何かもう既に申請をしているのかどうなのか。東京２０２０応援プログラムのほうも、この意味がちょっと僕はわからなくて、どういう意味なのかというのを説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"１０月１日から認証事業開始とありまして、品川区のほうにも事前にこういったプログラムの照会等はございました。そういった動向を見据えないと、中途半端にご紹介するのは混乱を招くだけかなと、区としては考えているところです。","id":"exchange-076"},{"speaker":"いながわ委員","kind":"質問・要望","question":"８月１５日に申請をしても１０月１日以降ですよという解釈でいいのかどうなのかということと、「ああ、しっかりやってほしいと求めました。地域団体にもこういう制度がありますよというのをどこかで広報してほしいと求めましたが、その辺一言お願いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"職員も相当ハードな、区としては、プログラムが認証されようがされまいがやることはきちんとやるというスタンスでいきたいと考えています。当初申し上げましたとおり、できるだけ多くの方が使いやすいように、こちらとしては一生懸命事務の簡素化等を求めているところです。","id":"exchange-077"},{"speaker":"いながわ委員","kind":"質問・要望","question":"この経済・テクノロジー、復興、そういうのにぜひ使用できるようにやってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"伊藤委員","kind":"質問","question":"東京２０２０参画プログラムと、それから品川区民芸術祭のことについて質問します。東京２０２０参画プログラムですけれども、それから、どこの誰がどういう権限でその内容を審査するのかということを説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"申請は必ず東京都を通じて組織委員会にいたします。認証を行うのは大会組織委員会です。","id":"exchange-079"},{"speaker":"伊藤委員","kind":"確認","question":"そのことの確認です。どのようなかかわり方なのか尋ねました。","respondent":"鈴木文化観光課長","answer":"基本的には品川区のほうの共催または後援等の名義をとっていただいて、実施主体が中心となってやったいただくものが主に含まれているものです。それから、ただし区民の方向けで少し一般よりは安くなっておりますが、そのような自主活動の事業ということで区分されているものです。","id":"exchange-080"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、例えばその枠を振り分けていくのでしょうかということ、企画展の部分では団体が何もしない可能性があるのでしょうかということ。そういうところはどのように品川区はＰＲしているのでしょうかということを説明を求めました。","respondent":"鈴木文化観光課長","answer":"普段から連携をしていただいている事業者や団体が連携をしてやるということですので、毎年大体七、八本の事業数は確保できております。それから会場であったり内容であるというものをやっておりますので、こちらのほうも比較的毎年十数本の確保ができているというのが現状です。","id":"exchange-081"},{"speaker":"伊藤委員","kind":"確認","question":"確認だけなのですけれども、当然品川区のガイドラインと言ったらいいのかな、審査のようなものがあるのでしょうか。同じようにサークル活動のしながわアマチュアステージの件についても同じですが、いかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"協賛事業の関係ですが、これは基本的に文化関係事業に係る品川区の名義使用の申請という制度があります。ほかの例えばスポーツであったり、それに適合すれば、基本的には大体審査の後に名義を使用していただけるものになっているものです。","id":"exchange-082"},{"speaker":"南委員","kind":"質問","question":"舟運・水辺の利活用のこととボランティアの育成・確保、そして交通整備（３５７号線、輸送計画）。交通整備は選手の輸送だとか、３５７号線というのは、あちらの潮風公園との関係で入ってくるという理解でよろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"どうしてもお伺いしたいのですけれども、都議会自民党がビーチバレーボールの会場について抜本的に見直すべきとの提言がされたと伺ったのですけれども、お伺いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/158474?Template=document&Id=6506#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":78195,"voices":191}},{"id":"h28-20161206-10","meetingId":"h28-cm12","date":"2016年12月6日","dateIso":"2016-12-06","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"途中ではありますが、先に予定表３、その他の(2)東京都後期高齢者医療広域連合議会の報告","agenda":"途中ではありますが、先に予定表３、その他の(2)東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"飯沼副委員長","kind":"質問・要望","question":"特に低所得者の方々のところの負担が２倍とか３倍にはね上がってしまうという問題が、何か議論されたのか、ご意見があったのか。例えば東京都にそのかわりを求めていくとか、何か手だてがないのかと思っているのですが、その辺の議論がどのようであったか教えていただきたい。","respondent":"本多議員","answer":"引き上げを極力しない方法で考えたというのは、執行側としては「極力抑えました」という、そういった説明をしておりました。できれば、資料をぜひご覧いただければわかると思います。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701951?Template=document&Id=5206#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":11580,"voices":45}}]);
